insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('lake-clark-alaska', '12A', 'Lake Clark National Park', 'United States', 'Coastal brown bears, volcanoes and Proenneke''s cabin', 'future', 'verified', 'mountainValley', 'Alaska', '{"wildlife","adventure","hiking","culture","expedition","parks"}', '{"remote","wild","dramatic","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Chinitna Bay bear viewing","source":"https://www.nps.gov/lacl/planyourvisit/chinitna-bay.htm","accessed":"2026-10-03","si":["wildlife","adventure","group","senior"],"booking_route":"none needed in the park - no entrance pass; reached by air taxi or a guided bear-viewing operator","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"Located at the southern end the park''s Cook Inlet coast, Chinitna Bay offers world class bear viewing. Visitors may be able to see as many as twenty coastal brown bears from a single location.\" \"Most visitors arrive in a small plane operating on wheels that lands on the beach\" - under an hour from Homer, Kenai or Anchorage - or by boat from Homer Harbor, \"four to five hours\". Three designated viewing sites with marked trails; the sedge meadow beyond the river is closed due to high bear use."},{"name":"Silver Salmon Creek","source":"https://www.nps.gov/lacl/planyourvisit/silver-salmon-creek.htm","accessed":"2026-10-03","si":["wildlife","adventure","senior"],"booking_route":"none needed in the park; reached by wheeled plane on the beach or a lodge transfer","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Located midway up the park''s Cook Inlet coast, this is the place to be if you are interested in bear viewing or fishing.\" Bears graze the sedge meadows late spring to mid-summer and fish in late summer; \"Coho (silver) salmon and humpback (pink) salmon as well as Dolly Varden run up the creek in the late summer.\" Ranger station on the south side of the creek; the sedge meadow \"is closed to human entry between the Sargent Creek confluence and the Silver Salmon Creek from June 15 to September 15 for habitat restoration.\""},{"name":"Crescent Lake","source":"https://www.nps.gov/lacl/planyourvisit/crescent-lake.htm","accessed":"2026-10-03","si":["wildlife","adventure"],"booking_route":"none needed in the park; reached by floatplane","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Crescent Lake is tucked into the coastal Chigmit Mountains, with views of Redoubt Volcano, high bear populations, and strong salmon runs\" - \"the park''s most visited destination.\" \"Sockeye / red salmon arrive during the month of July, while coho/silver salmon come in mid August through early September.\" \"Camping is not recommended at Crescent Lake due to the high number of bears in the area\"."},{"name":"Proenneke Cabin, Upper Twin Lake","source":"https://www.nps.gov/lacl/planyourvisit/visit-proenneke-cabin.htm","accessed":"2026-10-03","si":["culture","senior","hiking"],"booking_route":"none needed - a free historic site; reached by floatplane","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"Richard Proenneke''s home on Upper Twin Lake is a popular destination for visitors to the park\", on the lake''s south shore \"immediately up-lake of the Hope Creek delta.\" \"Open: Late May (tentative) through late September\", 10:00 AM to 4:00 PM for 2026, with rangers and volunteers housed nearby. \"Visitors arrive by small planes that land on Upper Twin Lake\" - just over an hour from Anchorage, typically 30 minutes from Port Alsworth. \"Camping is prohibited within the National Historic Register boundaries\"."},{"name":"Tanalian Falls Trail","source":"https://www.nps.gov/lacl/planyourvisit/day-hikes.htm","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - free park trail from Port Alsworth","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"Length: about 4 miles round trip\": \"Meander through birch groves and up spruce studded hillsides to a stunning view of Lake Clark\", to a 30-foot waterfall over ancient lava. The Tanalian trails network \"begins in town\" at Port Alsworth."},{"name":"Port Alsworth Visitor Center","source":"https://www.nps.gov/lacl/planyourvisit/port-alsworth.htm","accessed":"2026-10-03","si":["family","senior","hiking"],"booking_route":"none needed - free; 1 Park Place, Port Alsworth, AK 99653; 907-644-3626","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"The visitor center is located midway up the easternmost runway\" at the park''s field headquarters, \"Open in the summer only.\" \"The visitor center has a wheelchair accessible ramp. A fat tire wheelchair that works well on gravel is available from the Park HQ\". Port Alsworth \"offers visitor services such as lodging, air taxis, guide services, gear rentals, post office, and park visitor center.\""},{"name":"Lake Clark Junior Ranger programme","source":"https://www.nps.gov/lacl/learn/kidsyouth/junior-ranger.htm","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"none needed - free, in person or by mail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"Pick up your free Junior Ranger Activity Book at the Visitor Center in Port Alsworth, or speak with a backcountry ranger\"; or \"Download a PDF of Junior Ranger Journey and Where There Are Bears to print out on your own or email us to request a copy of the Activity Book and Badge to be mailed to you.\" A ranger signs the book, leads the pledge and presents \"an official badge.\""},{"name":"Kontrashibuna Lake Trail","source":"https://www.nps.gov/lacl/planyourvisit/day-hikes.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"Length: about 5.5 miles round trip\": \"Beyond Tanalian Falls, the trail enters Lake Clark''s designated wilderness on its way to the serenity of Kontrashibuna Lake, a spectacular mountain gem.\" \"Intrepid hikers with more time can extend a trip beyond Kontrashibuna Lake into the trailless high country.\""},{"name":"Tanalian Mountain Trail","source":"https://www.nps.gov/lacl/planyourvisit/day-hikes.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Length: 8.6 miles round trip\": \"The trail up Tanalian Mountain is steep and rigorous with stunning panoramic views of Lake Clark and the surrounding mountains\"; it needs at least eight hours."},{"name":"Beaver Pond Trail","source":"https://www.nps.gov/lacl/planyourvisit/day-hikes.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Length: 3.2 miles round trip\": \"This trail meanders through quiet birch groves and past an old beaver pond where shorebirds nest in the early summer.\""},{"name":"Priest Rock Public Use Cabin","source":"https://www.nps.gov/lacl/planyourvisit/priest-rock-cabin.htm","accessed":"2026-10-03","si":["adventure","family","group"],"booking_route":"Recreation.gov (facility 259345)","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":11,"blurb":"On Lake Clark''s north shore about 8 miles from Port Alsworth: \"Stay in a rustic cabin to experience remote Alaska living for yourself.\" Sleeps up to six (three single beds and one queen); \"$65 per night\"; maximum \"5 nights for a limit of 21 nights in a calendar year.\" \"Cabin is only accessible by floatplane or boat; water taxis may be available from Port Alsworth.\""},{"name":"Hope Creek campsite, Upper Twin Lake","source":"https://www.nps.gov/lacl/planyourvisit/visit-proenneke-cabin.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"none needed - first-come, first-served","commission_status":"none","tier_absent_reason":"not-sold","wells":["stay"],"draw_rank":12,"blurb":"\"Primitive camping area with no services\" on Upper Twin Lake with bear-resistant boxes provided; a creek crossing leads to the Proenneke cabin. \"Camping at Hope Creek Campsite is limited to a total of 14 days,\" with first-come, first-served hardened tent sites."},{"name":"Wild river rafting: Mulchatna, Chilikadrotna, Tlikakila","source":"https://www.nps.gov/lacl/planyourvisit/things2do.htm","accessed":"2026-10-03","si":["adventure","river","wildlife"],"booking_route":"none needed - self-supported, by air-taxi drop-off","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"The NPS names the \"Mulchatna, Chilikadrotna, Tlikakila\" rivers for rafting, and notes that visitors do not need fees or permits for river running. \"With 187 species documented in the park, Lake Clark is a fantastic place to visit for birding.\""},{"name":"Nat Hab''s Alaska Bear Camp, Chinitna Bay","source":"https://www.nathab.com/accommodations/alaska-bear-camp","accessed":"2026-10-03","si":["wildlife","expedition","group"],"booking_route":"sold only inside Natural Habitat Adventures trips; 800-543-8917","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":14,"blurb":"Natural Habitat Adventures'' camp at Chinitna Bay, Lake Clark National Park: ten handcrafted cabins with twin beds, en suite bathroom, hot running water and propane heat; \"Located on the ancestral lands of the Dena''ina people, Alaska Bear Camp is designed to tread lightly\" - on a historic homestead, the only privately held inholding grandfathered within the park since 1980. Guests arrive by chartered bush plane from Homer, landing on the beach in front of camp. The NPS lists it among Chinitna Bay lodging, (800) 543-8917."},{"name":"Alaska Bear Camp Photo Expedition (Natural Habitat Adventures)","source":"https://www.nathab.com/alaska-nature-tours/nat-hab-bear-camp-photo-expedition","accessed":"2026-10-03","si":["group","senior","wildlife","expedition"],"booking_route":"own website / 800-543-8917","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"A 7-day multi-day guided trip \"Limited to 14 travelers\": it begins with a chartered bush plane flight from Homer across Cook Inlet to the camp on a 15-acre inholding within Lake Clark National Park; bears watched from a two-story viewing platform, on foot with naturalist guides and from the Bear Mobile. Departure month July; \"From $10695 (+air)\"."},{"name":"Silver Salmon Creek Lodge","source":"https://www.silversalmoncreek.com/","accessed":"2026-10-03","si":["wildlife","adventure","group"],"booking_route":"phone (907) 690-1299 or email","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":16,"blurb":"\"Silver Salmon Creek Lodge is a premier vacation destination for wildlife photography, world-class sport fishing and Alaska bear viewing\", \"along the western shores of Cook Inlet\"; \"a one hour flight by small plane from Anchorage\". \"Bear viewing services are offered from June through mid-September\"; \"1-7 day excursions\" with \"a choice of a fully catered trip or remote tent camping.\" (907) 690-1299."},{"name":"Redoubt Mountain Lodge, Crescent Lake","source":"https://www.redoubtlodge.com/","accessed":"2026-10-03","si":["wildlife","adventure","romance"],"booking_route":"own website reservations","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":17,"blurb":"\"Redoubt Mountain Lodge is exclusively located on the glacier-fed waters of Crescent Lake in the heart of Lake Clark National Park, Alaska\", about 8 miles from 10,197-foot Redoubt Volcano. \"Accessible only by floatplane or helicopter and being the only lodge or privately owned property in the area\"; bear viewing, fishing, hiking, kayaking and helicopter fly-outs."},{"name":"Lake Clark Resort (The Farm Lodge), Port Alsworth","source":"https://www.lakeclarkresort.com/","accessed":"2026-10-03","si":["adventure","wildlife","family","senior"],"booking_route":"own website packages","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":18,"blurb":"Operates \"The Farm Lodge\" on the southwest shore of Lake Clark, within walking distance of park headquarters and trailheads; onsite cabins plus \"Wilderness Cabins\" about a 10-minute walk away; all-inclusive packages with bear viewing, fishing, flightseeing, rafting and Proenneke cabin trips; June through September; run by the Alsworth family since 1977."},{"name":"Ultimate Alaska Adventure package (Lake Clark Resort)","source":"https://www.lakeclarkresort.com/service-page/package-5","accessed":"2026-10-03","si":["group","senior","wildlife"],"booking_route":"own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","stay"],"draw_rank":19,"blurb":"A 9-day package from Port Alsworth: lodging with private bath, \"home-cooked Alaskan meals\", scenic bush plane tours (Lake Clark Pass, Katmai, Alaska Peninsula), \"Guided bear viewing\" at Brooks Camp in Katmai, mountain-lake tours, a boat tour on Lake Clark and local hiking. The price shown on the page was not a usable figure and is not stated here."},{"name":"Rust''s Flying Service - Lake Clark National Park Bear Viewing","source":"https://flyrusts.com/bearviewing/lake-clark-national-park-bear-viewing/","accessed":"2026-10-03","si":["wildlife","senior","group"],"booking_route":"''Book Now'' link to TripAdvisor; or 907-243-1595 / 1-800-544-2299","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":20,"blurb":"From Lake Hood, Anchorage (\"Lake Hood''s oldest and largest seaplane operator\"): \"Enjoy an hour and ten-minute stunning flightseeing tour via floatplane from Anchorage to Lake Clark National Park and Preserve\"; bears viewed at Crescent Lake \"by covered pontoon boat to lakeside areas where bears feed on spawning wild Alaska salmon\". \"11 hours Departs 9am\", \"August 1 - September 25\"; $1,445 per person plus 3% transportation tax and $15 NPS fee."},{"name":"Smokey Bay Air, Homer","source":"https://smokeybayair.com/","accessed":"2026-10-03","si":["wildlife","adventure"],"booking_route":"phone 907-531-0602 / 888-482-1511 or reservations@smokeybayair.com","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":21,"blurb":"\"Fly from scenic Homer, Alaska across the Cook Inlet to either Katmai National Park or Lake Clark National Park to view brown bears\"; it calls Lake Clark \"home to the highest concentrations of Alaskan Grizzly/Coastal Brown Bears\". Listed by the NPS as a Homer air taxi. 907-531-0602."},{"name":"Alaska West Air, Kenai","source":"https://www.alaskawestair.com/","accessed":"2026-10-03","si":["wildlife","adventure"],"booking_route":"phone (907) 283-4292","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":22,"blurb":"\"Delivering unforgettable Alaska tours in Kenai, AK, since 1978\" from \"the heart of the Kenai Peninsula\": bear viewing, fly-out fishing, hunting, flightseeing and custom charters on a fleet of nine aircraft. Listed by the NPS as a Kenai/Soldotna air taxi for Lake Clark. (907) 283-4292."},{"name":"Lake Clark Air","source":"https://lakeclarkair.com/","accessed":"2026-10-03","si":["adventure","family","senior"],"booking_route":"phone 907-278-2054 (Anchorage) / 907-781-2211 (Port Alsworth)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly","move"],"draw_rank":23,"blurb":"\"Service You Can Count On Since 1977\" - founded by bush pilot Glen Alsworth Sr.; seat fares, charters and freight with offices in Port Alsworth (907-781-2211) and at Merrill Field, Anchorage (907-278-2054). The NPS lists it for flights from both Anchorage and Port Alsworth."},{"name":"Tulch''ina Adventures campground and cabins, Port Alsworth","source":"https://www.tulchinaadventures.com/","accessed":"2026-10-03","si":["adventure","family","group"],"booking_route":"phone (907) 782-4720 or info@tulchinaadventures.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","move"],"draw_rank":24,"blurb":"\"Cabin rentals and campground in Port Alsworth, AK\" - the Tanalian Cabin and Dry Creek Cabins - plus \"Water taxi, charter boat and freight services on Lake Clark\". The NPS names it as Port Alsworth''s one privately operated campground. 1 Tanalian Point; (907) 782-4720."},{"name":"Tulch''ina Adventures kayak and gear rentals","source":"https://www.tulchinaadventures.com/","accessed":"2026-10-03","si":["adventure","hiking","river"],"booking_route":"phone (907) 782-4720 or info@tulchinaadventures.com","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities"],"draw_rank":25,"blurb":"\"Kayak and gear rentals for Lake Clark National Park\" from Port Alsworth, alongside its water taxi to the lake''s cabins and trailheads. No rates are published on the page."},{"name":"Homer Spit Campground","source":"https://www.homerspitcampground.com/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"own website Book Now portal","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"\"WHERE THE LAND ENDS AND THE SEA BEGINS\": \"large, full hookup sites for motorhomes up to 40''\" and \"Small tent spaces for the lone backpacker\"; \"2026 season May 6th - September 9th\", online reservations opening January 1, 2026; 4535 Homer Spit Road - the spit is where the Homer bear-viewing flights and boats depart."},{"name":"Kilcher Homestead MiracleMeadow, Homer","source":"https://www.hipcamp.com/en-US/land/alaska-kilcher-homestead-miraclemeadow-mxvhk1vr","accessed":"2026-10-03","si":["glamping","family","culture"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"On the Kilcher Homestead, hosted by Stellavera Kilcher: glamping in the \"Awesome Glamping Island Tent\" (canvas, sleeps 4), the \"Kilcher Homestead Lighthouse\" cabin with heater and a cedar cabin, plus a $45/night tent site; \"full outdoor kitchen\", views of glaciers and Kachemak Bay; Homer is \"35 minutes away\"."},{"name":"Seaside Farm, Kachemak Bay","source":"https://www.hipcamp.com/en-US/land/alaska-seaside-farm-j29h9rey","accessed":"2026-10-03","si":["glamping","family","group"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"A 30-acre farm on Kachemak Bay near Homer, listed by Hipcamp under Cabins & Glamping: three cabins (Seashell, Beach Hideaway, Wildflower), 10 tent sites and 4 van sites; covered camping pavilion with outdoor kitchen, \"trails, lawns, gardens, trees, hay fields, and a private beach\"."},{"name":"The Saltry, Halibut Cove","source":"https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/homerak/Dining_Guide_7_8_26_54e2e5be-5abd-47ae-be19-d80ff72ec65d.pdf","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"phone 907-226-2424","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"Listed by the Homer Chamber of Commerce under the bay: \"The Saltry Halibut Cove SUN-SAT Fine Dining | 907-226-2424\" (Dining Guide, \"Updated July 8, 2026\")."},{"name":"Land''s End Chart Room","source":"https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/homerak/Dining_Guide_7_8_26_54e2e5be-5abd-47ae-be19-d80ff72ec65d.pdf","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"phone 907-235-0406","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":30,"blurb":"Homer Chamber of Commerce Dining Guide: \"Land''s End Chart Room 4786 Homer Spit Rd. SUN-SAT Seaside Fine Dining | 907-235-0406\"."},{"name":"Captain Pattie''s Fish House","source":"https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/homerak/Dining_Guide_7_8_26_54e2e5be-5abd-47ae-be19-d80ff72ec65d.pdf","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"phone 907-235-5135","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"Homer Chamber of Commerce Dining Guide: \"Captain Pattie''s Fish House 4241 Homer Spit Rd. SUN-SAT Seafood | 907-235-5135\"."},{"name":"La Baleine Cafe","source":"https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/homerak/Dining_Guide_7_8_26_54e2e5be-5abd-47ae-be19-d80ff72ec65d.pdf","accessed":"2026-10-03","si":["culinary"],"booking_route":"phone 907-299-6672","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"Homer Chamber of Commerce Dining Guide: \"La Baleine Cafe 4460 Homer Spit Rd. WED-SUN Locally Sourced Cafe |907-299-6672\"."},{"name":"Harbor Grill","source":"https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/homerak/Dining_Guide_7_8_26_54e2e5be-5abd-47ae-be19-d80ff72ec65d.pdf","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"phone 907-235-9333","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"Homer Chamber of Commerce Dining Guide: \"Harbor Grill 4264 Homer Spit Rd. SUN-SAT Seafood & Steak | 907-235-9333\"."},{"name":"Fat Olives Restaurant","source":"https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/homerak/Dining_Guide_7_8_26_54e2e5be-5abd-47ae-be19-d80ff72ec65d.pdf","accessed":"2026-10-03","si":["culinary","family","group"],"booking_route":"walk-in (no booking method in the guide)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"Homer Chamber of Commerce Dining Guide: \"Fat Olives Restaurant 276 Ohlson Ln. SUN-SAT Pizza, seafood, pasta, sandwiches\"."},{"name":"Homer Brewing Company","source":"https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/homerak/Dining_Guide_7_8_26_54e2e5be-5abd-47ae-be19-d80ff72ec65d.pdf","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in; 907-235-3626","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"Homer Chamber of Commerce Dining Guide: \"Homer Brewing Company 1411 Lakeshore Dr. SUN-SAT Traditional Brewery | 907-235-3626\"."},{"name":"AJ''s OldTown Steakhouse","source":"https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/homerak/Dining_Guide_7_8_26_54e2e5be-5abd-47ae-be19-d80ff72ec65d.pdf","accessed":"2026-10-03","si":["culinary","group"],"booking_route":"phone 907-235-9949","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"Homer Chamber of Commerce Dining Guide: \"AJ''s OldTown Steakhouse 120 W. Bunnell Ave. TUE-SAT Steaks & Seafood | 907-235-9949\"."},{"name":"Bear-resistant food container for every camp","source":"https://www.nps.gov/lacl/planyourvisit/bear-safety.htm","accessed":"2026-10-03","si":["hiking","adventure","wildlife"],"booking_route":"free loan at the Port Alsworth visitor center; to own one, affiliate referral to BearVault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":37,"blurb":"NPS: \"Proper Food Storage is Required\"; \"A bear resistant food container must hold all scented items, including toothpaste and sunscreen - not just food.\" The park \"offers bear resistant containers for temporary use by visitors free of charge at the park visitor center in Port Alsworth.\" At Crescent Lake caught fish must be \"secured in an approved bear-resistant container as soon as you catch it.\""},{"name":"Bear spray, carried ready","source":"https://www.nps.gov/lacl/planyourvisit/bear-safety.htm","accessed":"2026-10-03","si":["hiking","wildlife","adventure"],"booking_route":"affiliate referral to Counter Assault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":38,"blurb":"NPS: \"Unholster your bear spray and be prepared to use it if necessary\"; \"Use pepper spray if the bear comes within range if you have it.\" In an encounter: \"Remain calm and do not run.\" \"If it is a brown bear, play dead.\" \"If it is a black bear, fight back vigorously!\""},{"name":"Rain gear, waterproof footwear and layers","source":"https://www.nps.gov/lacl/planyourvisit/weather.htm","accessed":"2026-10-03","si":["hiking","adventure","senior","family"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":39,"blurb":"NPS: \"Sturdy rain gear and waterproof footwear are a must, and smart travelers make sure to layer clothing.\" \"The coast is often foggy and wet, with an average annual rainfall of 40 to 80 inches\"; on the Tanalian trails, \"make sure you are prepared to spend the night if unexpected weather makes that necessary.\""}],"faq":[{"q":"How do you get to Lake Clark National Park?","a":"By small plane. The NPS: \"Like many areas in Alaska, Lake Clark is not on the road system and travel takes place primarily by small plane.\" The park is \"65 air miles northwest of Homer, and about 120 air miles southwest of Anchorage\", and the NPS lists air taxis from Anchorage, Homer, Kenai or Soldotna, King Salmon, Kodiak, Port Alsworth and Wasilla.","source":"https://www.nps.gov/lacl/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you drive to Lake Clark National Park?","a":"No. \"Lake Clark is not on the road system; therefore, access is primarily by small aircraft.\"","source":"https://www.nps.gov/lacl/planyourvisit/index.htm","accessed":"2026-10-03"},{"q":"Can you get to Lake Clark National Park by boat?","a":"On the coast, sometimes: \"When weather and tides permit, the east side of the park on the Cook Inlet coast may be accessed by boat via an open-ocean crossing.\" To Chinitna Bay, boat travel from Homer Harbor takes \"four to five hours\" over \"approximately 60 miles\".","source":"https://www.nps.gov/lacl/planyourvisit/chinitna-bay.htm","accessed":"2026-10-03"},{"q":"What is the best time to see bears in Lake Clark National Park?","a":"The NPS describes two seasons on the coast: late spring through mid-summer, when bears graze the sedge meadows, and late summer, when they gather at the rivers for the salmon - \"Coho (silver) salmon and humpback (pink) salmon as well as Dolly Varden run up the creek in the late summer\" at Silver Salmon Creek.","source":"https://www.nps.gov/lacl/planyourvisit/silver-salmon-creek.htm","accessed":"2026-10-03"},{"q":"How big is Lake Clark National Park?","a":"\"Comprised of 4 million acres on the Alaska Peninsula in southwest Alaska.\"","source":"https://www.nps.gov/lacl/planyourvisit/basicinfo.htm","accessed":"2026-10-03"},{"q":"When was Lake Clark National Park established?","a":"\"Established by the Alaska National Interest Lands Conservation Act (ANILCA) on December 2, 1980.\"","source":"https://www.nps.gov/lacl/planyourvisit/basicinfo.htm","accessed":"2026-10-03"},{"q":"Can you camp at Lake Clark National Park?","a":"Yes. Backcountry camping is generally permitted with bear-resistant canisters required; Hope Creek on Upper Twin Lake is a \"Primitive camping area with no services\" with bear-resistant boxes; Port Alsworth has one privately operated campground. Camping is prohibited at the Proenneke Historic Site, and the Chinitna Bay sedge meadow is closed to camping May 1-August 31.","source":"https://www.nps.gov/lacl/planyourvisit/eating-sleeping.htm","accessed":"2026-10-03"},{"q":"Does Lake Clark National Park have a visitor center?","a":"Yes, in Port Alsworth: \"The visitor center is located midway up the easternmost runway\", \"Open in the summer only.\" Winter visitors may contact staff at the headquarters building next door.","source":"https://www.nps.gov/lacl/planyourvisit/port-alsworth.htm","accessed":"2026-10-03"},{"q":"Do you need tickets for Lake Clark National Park and Preserve?","a":"No: \"An entrance pass is not required to access Lake Clark National Park & Preserve.\" The public use cabins carry fees and \"Reservations are required.\"","source":"https://www.nps.gov/lacl/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you fish in Lake Clark National Park?","a":"Yes. At Crescent Lake \"Sockeye / red salmon arrive during the month of July, while coho/silver salmon come in mid August through early September\", and any fish caught must be \"secured in an approved bear-resistant container as soon as you catch it.\"","source":"https://www.nps.gov/lacl/planyourvisit/crescent-lake.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Lake Clark National Park: Bears, Proenneke Cabin & Fly-In Lodges | TravelWell","meta_description":"No road and no entrance fee: fly in from Homer or Anchorage for brown bears at Chinitna Bay and Crescent Lake, Proenneke''s cabin, and fly-in lodges.","slug":"lake-clark-national-park-alaska","primary_keyword":"Lake Clark National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Lake Clark National Park brown bears Chinitna Bay"}}'::jsonb, 108),
  ('gates-of-the-arctic-alaska', '12A', 'Gates of the Arctic National Park', 'United States', 'Roadless Brooks Range wilderness and rivers', 'future', 'verified', 'mountainValley', 'Alaska', '{"adventure","hiking","expedition","wildlife","culture","parks"}', '{"remote","wild","rugged","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Trail-less Brooks Range backpacking","source":"https://www.nps.gov/gaar/planyourvisit/backpackingandhiking.htm","accessed":"2026-10-03","si":["hiking","adventure","expedition","group"],"booking_route":"none needed - no entrance pass or registration; reached by air taxi or on foot from the Dalton Highway or Anaktuvuk Pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"NPS: \"Backpackers have 8.4 million acres of spectacular wilderness in which they can wander at will.\" There are no designated trails; \"Topographic maps are essential in planning your course of travel\", and \"Group size limit is 10 people, to minimize impacts to the environment.\" The NPS names Boreal Mountain and Frigid Crags above the Koyukuk River."},{"name":"Six Wild Rivers float trips","source":"https://www.nps.gov/gaar/learn/nature/wildandscenicrivers.htm","accessed":"2026-10-03","si":["river","adventure","expedition","group"],"booking_route":"none needed in the park; self-outfitted or with a guided rafting operator, dropped by air taxi","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"The park holds six designated Wild Rivers - the Alatna, John, Kobuk, Noatak, North Fork Koyukuk (which \"flows south through the ''Gates of the Arctic''\") and Tinayguk. \"Waters average Class I and II, with a few Class II-IV rapids\"; \"the highest water is in May and June.\" The NPS weather page: \"July through August is generally the best time to take float trips.\""},{"name":"Anaktuvuk Pass Nunamiut village","source":"https://www.nps.gov/gaar/planyourvisit/anaktuvuk.htm","accessed":"2026-10-03","si":["culture","hiking","adventure"],"booking_route":"none needed - scheduled flight from Fairbanks; designated camping by the airstrip","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Situated inside the park''s boundaries, at the top of a wide 2,100 foot mountain pass, the village of Anaktuvuk Pass is a great place to start your exploration of Gates of the Arctic.\" \"Accessible by commercial air service from Fairbanks.\" The city council designated camping \"around the access road on the east side of the airstrip\"; private lands: \"There is no allowed permission to travel across or camp on these parcels of private property.\" Ranger station \"Staffed each year between April to the end of September.\""},{"name":"Simon Paneak Memorial Museum","source":"https://www.nps.gov/gaar/planyourvisit/anaktuvuk.htm","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"pay at the door; phone 907-661-3413","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":6,"blurb":"In Anaktuvuk Pass: \"Exhibits on Nunamiut history, life, and culture\", admission listed by the NPS at $20, phone 907-661-3413. The NPS history page: \"In the late 1940s bands of nomadic Nunamiut Eskimos settled in Anaktuvuk Pass. Today their village represents a combination of modern and traditional lifeways.\""},{"name":"Bettles Ranger Station and visitor center","source":"https://www.nps.gov/gaar/planyourvisit/bettles.htm","accessed":"2026-10-03","si":["senior","family","group","hiking"],"booking_route":"none needed - free; open 7 days a week July 1 to September 25 (accessibility page)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"Bettles hosts a park visitor center, where travelers attend backcountry orientations, receive park condition updates, attend ranger programs, stamp their national park passport, and check out bear resistant food containers.\" Bettles Field sits \"around 20 miles south of the southern boundaries\" of the park, reached by \"scheduled commercial air service from Fairbanks.\" The accessibility page: entrance \"via an ADA accessible ramp. Accessible restrooms are available.\""},{"name":"Gravel-bar and lakeshore camping","source":"https://www.nps.gov/gaar/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","adventure","river","expedition"],"booking_route":"none needed - dispersed backcountry camping, no reservations","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities","stay"],"draw_rank":8,"blurb":"\"There are no designated campsites in Gates of the Arctic National Park and Preserve.\" \"Gravel bars make excellent campsites since they often have fewer mosquitoes than other sites, and high water will erase signs of your presence\" - but \"locate your camp well above current water levels.\" The NPS suggests \"moving camp every 2-3 days\" and keeping \"tent, cook, and BRFC are all 100 yards apart in a triangle formation.\""},{"name":"Agiak Lake hunting blinds and inuksuit","source":"https://www.nps.gov/gaar/learn/historyculture/places.htm","accessed":"2026-10-03","si":["culture","hiking","expedition"],"booking_route":"none needed - backcountry, reached by air taxi","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"An NPS place page: Agiak Lake has \"stone hunting blinds and hundreds of rock cairns (inuksuit)\" used in caribou hunting practiced for thousands of years. \"People have lived in the Brooks Range for more than 13,000 years and thousands of archeological sites in Gates of the Arctic document this history.\" Leave all \"cultural, and historical resources where you found them\" (camping page)."},{"name":"Preserve sport hunting under state licence","source":"https://www.nps.gov/gaar/planyourvisit/hunting.htm","accessed":"2026-10-03","si":["adventure","wildlife","expedition"],"booking_route":"State of Alaska licence via the Alaska Department of Fish and Game; guided hunts through an NPS-authorized guide","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":20,"blurb":"NPS: \"Sport hunting and trapping are permitted in Gates of the Arctic National Preserve, but not in Gates of the Arctic National Park.\" An Alaska State hunting licence is required for hunters 16 or older, under State regulations for Game Management Units 23, 24 and 26; guided hunts need an NPS Concession Contract or Commercial Use Authorization."},{"name":"Caribou, bears, Dall sheep and muskox","source":"https://www.nps.gov/gaar/learn/nature/wildlife.htm","accessed":"2026-10-03","si":["wildlife","hiking","river","senior"],"booking_route":"none needed - seen in the backcountry or from a flightseeing aircraft","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"NPS wildlife page: \"Caribou trek from their boreal forest wintering grounds to their calving areas on the coastal plain\"; \"Grizzly and black bears leave their dens with cubs born the previous winter\"; Dall''s sheep, muskox, lynx, beavers and snowshoe hares each carry their own section, and \"Whitefish, northern pike and grayling feast in the rivers and lakes.\""},{"name":"Winter aurora and ski or dog travel","source":"https://www.nps.gov/gaar/planyourvisit/weather.htm","accessed":"2026-10-03","si":["expedition","adventure","ski"],"booking_route":"none needed in the park; aurora and mushing trips are sold by the gateway lodges","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"NPS: \"November through March is the best time for viewing the Aurora Borealis.\" \"February through April is a good time for winter travel with skis, snowshoes, or dogs\", with \"ice crossings, potential avalanche conditions and extreme temperatures (-50F or colder).\""},{"name":"Flightseeing, fishing and fly-in camp-outs","source":"https://www.nps.gov/gaar/planyourvisit/things2do.htm","accessed":"2026-10-03","si":["adventure","senior","wildlife","family"],"booking_route":"through an air taxi in Bettles, Coldfoot or Fairbanks","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"NPS things to do: \"Local air taxis provide flight-seeing trips, day trips or overnight camp-outs at remote locations.\" \"Spend the day fishing at an alpine lake, watching the caribou pass through northern valleys.\" \"Lakes and gravel bars provide camping spots surrounded by unparalleled natural beauty.\""},{"name":"Gates of the Arctic Base Camp (Arctic Wild)","source":"https://arcticwild.com/trip/base-camp/gates-of-the-arctic-national-park-camp-2027/","accessed":"2026-10-03","si":["group","senior","expedition","hiking","wildlife"],"booking_route":"reservation request form at arcticwild.com/reservation-form/, deposit required; info@arcticwild.com, 907.479.8203","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":10,"blurb":"A multi-day guided base camp in the central Brooks Range, August 9-13, 2027, $8,200: pre-trip meeting in Fairbanks, charter flight to a tundra base camp, three days of day hikes to \"glacial cirques, alpine lakes, ridges\", return to Fairbanks. \"You need not be a seasoned adventurer to enjoy this trip.\" Included: \"Transportation beyond Fairbanks, Food while in the wilderness, Stoves, cooking & eating utensils, Safety & repair gear, Professional guide service.\" Arctic Wild''s 2027 Gates list also carries a 4-day Gates and Kobuk Valley base camp ($9,100), a 10-day Noatak River canoe ($9,600) and an 11-day Arrigetch Peaks packraft ($9,900)."},{"name":"Arrigetch-Alatna Pack Raft (Alaska Alpine Adventures)","source":"https://www.alaskaalpineadventures.com/","accessed":"2026-10-03","si":["expedition","hiking","river","group","adventure"],"booking_route":"own website - alaskaalpineadventures.com/find-your-trip/","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":14,"blurb":"A guided \"Arrigetch-Alatna Pack Raft - Gates of the Arctic National Park\": 12 days, backpacking, multisport and rafting, \"35+ miles, 50+ river miles\", intensity Level 3, $8,195. The same operator lists the 10-day \"Oolah Valley High Route\" ($6,695) and a 12-day Noatak River and Great Kobuk Sand Dunes combination across Gates of the Arctic and Kobuk Valley ($9,695)."},{"name":"Bettles Lodge, the 1950 gateway lodge","source":"https://bettleslodge.com/accommodations/","accessed":"2026-10-03","si":["adventure","expedition","wildlife","culture"],"booking_route":"email info@bettleslodge.com or 1-907-692-5111; \"50% deposit\" at booking (FAQ)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":11,"blurb":"\"Bettles is located 35 miles north of the Arctic Circle\", the \"jumping off\" point for Gates of the Arctic, Noatak and Kobuk Valley; \"Serving the Arctic Traveler since 1950.\" The historic lodge was \"Completed in 1950\" and \"became recognized as a National Historic Site in the year 1996\": \"6 cozy rooms\", plus the Aurora Lodge''s \"4 Jacuzzi rooms\". Winter brings Northern Lights viewing, dog mushing and cross-country skiing. FAQ: \"Nope\" to wheelchair access - guests \"climb 4 stairs into the Cessna\"."},{"name":"National Park Collector fly-in day (Bettles Lodge)","source":"https://bettleslodge.com/summer/park-collector-package/","accessed":"2026-10-03","si":["senior","adventure","group","wildlife"],"booking_route":"info@bettleslodge.com, 1-907-692-5111 / 1-779-775-2990","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":21,"blurb":"\"Our same day ''National Park Collector Wilderness Adventure'' can take you to both the Gates of Arctic and Kobuk National Park in the same day\" by float plane (Cessna 180 or DeHavilland Beaver), with a picnic lunch and landings in the parks. \"We require at least two nights in Bettles to join on our National Park Adventure.\" No price on the page: \"Please contact us for price quotes and questions.\""},{"name":"Brooks Range Aviation, Bettles air taxi","source":"https://www.brooksrange.com/trips-tours/","accessed":"2026-10-03","si":["adventure","senior","river","hiking","expedition"],"booking_route":"airservice@brooksrange.com; Fairbanks 907-474-0595 (year-round), Bettles 907-692-5444 (June-September)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly","activities","move"],"draw_rank":13,"blurb":"Based at Bettles Field, flying \"Gates of Arctic National Park, Naotak National Preserve, Kobuk Valley National Park\" and the refuges. Its \"most popular tour\", Gates of the Arctic and Kobuk Valley, \"typically lasts 4 to 5 hours\" with landings, minimum two passengers, $1,995 per person for two down to $1,595 for six. Gates routes land at an Arrigetch Peaks lake or fly the North Fork Koyukuk \"through ''The Gates''\"; unguided float-plane drop-offs for the Noatak, John, Alatna and Killik rivers."},{"name":"Iniakuk Lake Wilderness Lodge","source":"https://www.gofarnorth.com/","accessed":"2026-10-03","si":["wildlife","ultra","romance","adventure"],"booking_route":"(877) 479-6354 or iniakuk@gmail.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":16,"blurb":"\"Iniakuk Lake Wilderness Lodge is an exclusive fly-in luxury wilderness lodge 220 miles (350 km) north of Fairbanks in Alaska''s Brooks Range\", on the edge of Gates of the Arctic, family-owned since 1974 and built by hand from local logs. Winter February 20 - April 10, summer June 20 - September 10; \"all-inclusive fly-out tours begin and end in Fairbanks\". Northern lights, dog mushing, float trips, hiking, canoeing, fishing."},{"name":"Arctic Interagency Visitor Center, Coldfoot","source":"https://www.blm.gov/learn/interpretive-centers/arctic-interagency-visitor-center","accessed":"2026-10-03","si":["family","group","senior","culture"],"booking_route":"none needed - free; group programmes arranged in advance","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"At \"Milepost 175\" of the Dalton Highway: exhibits and films on the Arctic, an \"evening program\", \"Educational programs for groups\" by advance arrangement, trip planning, bear barrel loans and \"Backcountry registration for Gates of the Arctic National Park and Preserve.\" \"Open 12 p.m. - 9 p.m., late May through mid-September, including holidays.\" Entry is free."},{"name":"Slate Creek Inn at Coldfoot Camp","source":"https://www.coldfootcamp.com/stay","accessed":"2026-10-03","si":["adventure","motoring","overland","group"],"booking_route":"online via the Mews booking engine linked from coldfootcamp.com; (907) 474-3500","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":15,"blurb":"Coldfoot Camp, \"Mile 175 Dalton Hwy\": \"Each cozy, clean room has two twin beds and a private bathroom with a shower\", in refurbished trailers that once housed pipeline construction workers. \"$259 per night single or double occupancy\" through Dec 1, 2025; $269 from January 1, 2026. Fully refundable until 7 days before arrival. Open year-round."},{"name":"Coldfoot Camp tent sites and RV hook-ups","source":"https://www.alaska.org/detail/coldfoot-camp","accessed":"2026-10-03","si":["motoring","overland","adventure"],"booking_route":"at the Coldfoot Camp front desk, (907) 474-3500","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":23,"blurb":"Coldfoot Camp''s own page: \"Camping is available at Coldfoot Camp during the summer months, free of charge\", with 24-hour cafe bathrooms and water; showers $14 at the front desk. Alaska.org adds: \"Limited RV hook-ups area available for a fee\" and \"Open May through September, weather permitting\" (alaska.org is a guide site; the camp''s own stay page does not mention hook-ups)."},{"name":"Marion Creek Campground (BLM)","source":"https://www.blm.gov/visit/marion-creek-campground","accessed":"2026-10-03","si":["motoring","hiking","family","overland"],"booking_route":"first-come, first-served; pay on site via the Recreation.gov app","commission_status":"none","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":22,"blurb":"At \"mile 180 of the Dalton Highway\", 5 miles north of Coldfoot: 27 campsites, \"Fourteen sites are pull-through\", \"$12 per night\", \"mid-May through end of September (depending on snowfall)\", \"first-come, first-serve basis only\" with payment by QR code through the Recreation.gov app. Potable water, vault toilets, fire rings, a camp host; no electricity or dump station."},{"name":"Wiseman Village Visit from Coldfoot","source":"https://www.coldfootcamp.com/excursions","accessed":"2026-10-03","si":["culture","senior","family","group"],"booking_route":"Coldfoot Camp, 907-474-3500","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":18,"blurb":"\"Drive thirteen miles North on the Dalton Highway and ''travel back in time'' to visit the historic gold mining village\" - $69 per person, year-round, booked at 907-474-3500. The NPS: Coldfoot and Wiseman sit \"along the Middle Fork of the Koyukuk River\", \"north of the Arctic Circle\", and \"Some lodging is available in the town\" of Wiseman. Winter adds the \"Arctic Village Aurora\" trip to Wiseman, August 21 to April 21, $89."},{"name":"Gates of the Arctic Air Adventure from Coldfoot","source":"https://www.coldfootcamp.com/excursions","accessed":"2026-10-03","si":["adventure","senior","family","river"],"booking_route":"Coldfoot Camp, 907-474-3500","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":24,"blurb":"Coldfoot Camp: \"Sightsee in some of the most remote parts of the Arctic via bush plane\" - a 1-hour flight, June through August, $329 per person. Also from the camp: \"Float down the Koyukuk River with an experienced raft guide!\" (mid-May to mid-September, $149) and the Arctic Mountain Safari \"past timberline to the Arctic tundra\" ($129)."},{"name":"Arctic Circle Midnight Sun Overnight Adventure (Northern Alaska Tour Company)","source":"https://www.northernalaska.com/tours/arctic-circle-midnight-sun-overnight-adventure/","accessed":"2026-10-03","si":["group","senior","motoring","culture","adventure"],"booking_route":"Northern Alaska Tour Company planning page; 800-474-1986","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","move"],"draw_rank":19,"blurb":"\"An Overnight Guided Round Trip Journey By Land And Air Into Alaska''s Brooks Mountain Range\" from Fairbanks: the Dalton Highway, the Arctic Circle Trading Post in Joy, the Yukon River, an overnight at Coldfoot Camp with optional Gates of the Arctic air flights, Wiseman visits and Koyukuk River floats. 3 days / 2 nights per the page; \"$639 *Per person based on double occupancy\" (April-June) and \"$739\" (June-August), 2027 season April 22 - August 20. The company: \"Northern Alaska Tour Company pioneered Arctic Circle touring on Alaska''s Dalton Highway.\""},{"name":"Gates of the Arctic Air Adventure from Fairbanks","source":"https://www.northernalaska.com/tours/gates-of-the-arctic-air-adventure/","accessed":"2026-10-03","si":["senior","adventure","group","family"],"booking_route":"Northern Alaska Tour Company planning page; 800-474-1986","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":26,"blurb":"Northern Alaska Tour Company: \"An Evening Round Trip Journey By Air In To The Gates Of The Arctic National Park\" - departs Fairbanks 7:00 PM, lands at Coldfoot \"60 miles north of the Arctic Circle\", flies through the park, back in Fairbanks between 11:30 PM and midnight. Daily \"June 1, 2027 - August 31, 2027\"; $749 per person (2026 rate), $769 (2027)."},{"name":"Arctic Getaway Cabin and Breakfast, Wiseman","source":"https://www.explorefairbanks.com/listing/arctic-getaway-cabin-%26-breakfast/10278/","accessed":"2026-10-03","si":["romance","culture","motoring"],"booking_route":"(907) 799-4455 or arcticgetaway@gmail.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"\"Located along the Dalton Highway north of Coldfoot, our cozy cabins are tucked away in Wiseman in the scenic foothills of the Brooks range.\" Three cabins with private bathrooms and kitchens, breakfast included, open year-round; nightly rates listed at $210 to $350."},{"name":"Wright Air Service scheduled flights","source":"https://www.wrightairservice.com/","accessed":"2026-10-03","si":["adventure","culture","hiking","senior"],"booking_route":"reservations (907) 474-0502, reservations@wrightairservice.com; charter desk (907) 474-0504","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly","move"],"draw_rank":28,"blurb":"\"Proudly Serving Alaska Since 1966\", from Fairbanks with daily scheduled service to over 40 interior and northern villages including Bettles, Anaktuvuk Pass and Coldfoot; charters to \"most locations in Alaska, including National Parks\", and flightseeing. Bettles Lodge''s FAQ: its guests fly Fairbanks-Bettles on Wright Air Service."},{"name":"Coldfoot Trucker''s Cafe buffets","source":"https://www.coldfootcamp.com/eat","accessed":"2026-10-03","si":["motoring","family","group"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"\"The Coldfoot Trucker''s Cafe is open year-round, but our offerings change seasonally.\" Summer: \"a full breakfast buffet from 5 am - 9 am, and a dinner buffet from 5 pm - 9 pm\" - breakfast $16.95, dinner $27.95, with discounts for children 12 and under; sack lunches to order. Winter: menu \"all day, from 5am to 12am.\""},{"name":"Frozen Foot Saloon, Coldfoot","source":"https://www.coldfootcamp.com/drink","accessed":"2026-10-03","si":["motoring","group"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":30,"blurb":"\"The Frozen Foot Saloon offers a variety of beer and wine for your enjoyment\" - Silver Gulch beers brewed in Fairbanks, Alaskan Amber and Matanuska, wines from Merlot to Moscato. \"We do not serve liquor at this time.\" Mile 175, Dalton Highway."},{"name":"Bettles Lodge dining room and bar","source":"https://bettleslodge.com/accommodations/","accessed":"2026-10-03","si":["adventure","group","senior"],"booking_route":"walk-in in summer; included in lodge packages","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"Summer: \"Full service dining room & bar in the Lodge lobby\" (accommodations page). Package guests: \"All meals, snacks, soft-drinks are included in your package price\" - \"hand cut steak or prime rib, Sockeye Salmon, chicken\" with \"Chef''s choice of starch, veg and dessert\" (FAQ, https://bettleslodge.com/faqs/)."},{"name":"Alaska Commercial store, Anaktuvuk Pass","source":"https://www.nps.gov/gaar/planyourvisit/anaktuvuk.htm","accessed":"2026-10-03","si":["hiking","culture","expedition"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":32,"blurb":"The NPS lists the village''s Alaska Commercial store, open \"Monday-Saturday 10-6. Closed Sundays.\", phone 907-661-3327 - the one place inside the park boundary to resupply food. The NPS basic info page: carry extra food provisions for weather delays that ground aircraft."},{"name":"Bettles Lodge camping supplies and cold-weather kit","source":"https://bettleslodge.com/faqs/","accessed":"2026-10-03","si":["hiking","expedition","adventure"],"booking_route":"buy at the lodge; info@bettleslodge.com","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","shop"],"draw_rank":33,"blurb":"The lodge sells \"Camping supplies (bear spray, fuel, propane)\" and has a gift shop (park collector page). Winter guests are kitted out: \"parkas, snow pants, heavy bunny boots or Sorel brand boots, gloves, mitts, ski goggles\", and rubber boots for float-plane access (FAQ). Summer advice: \"Always, always, bring your own rain gear\" and \"Have layers with you just in case.\""},{"name":"Arctic Wild raft and camping gear rentals","source":"https://arcticwild.com/trip/base-camp/gates-of-the-arctic-national-park-camp-2027/","accessed":"2026-10-03","si":["river","expedition","hiking"],"booking_route":"info@arcticwild.com, 907.479.8203","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities"],"draw_rank":34,"blurb":"Fairbanks-based Arctic Wild - \"Professionally guided Alaska adventure tours in Alaska''s vast wilderness\" - offers raft rentals (site navigation), and its Gates base camp page states camping gear is available for rental against the personal equipment list; personal clothing and fishing equipment are not included."},{"name":"Bear-resistant food container for every camp","source":"https://www.nps.gov/gaar/planyourvisit/brfcs.htm","accessed":"2026-10-03","si":["hiking","river","expedition","wildlife"],"booking_route":"free loan at Bettles, Coldfoot, Anaktuvuk Pass or Fairbanks; to own one, affiliate referral to BearVault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":35,"blurb":"NPS: \"Proper food storage (certified bear resistant food container) is required in all Alaskan parks\" (camping page). \"Gates of the Arctic ranger stations and visitor centers have a variety of BRFCs available for loan, free of charge, on a first come, first served basis\"; they can be returned to any ranger station or by mail. Coolers, plastic totes, dry bags and kayaks are not approved."},{"name":"Bear spray, carried ready","source":"https://www.nps.gov/gaar/planyourvisit/bearsafety.htm","accessed":"2026-10-03","si":["hiking","wildlife","adventure"],"booking_route":"affiliate referral to Counter Assault (AvantLink); sold at Bettles Lodge","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":36,"blurb":"NPS: \"Bear spray (Capsicum spray) is also an effective deterrent in bear encounters\", effective at 15-20 feet; do not spray downwind. The park holds grizzly and black bears: for brown bear contact, play dead; for black bears, fight back - never play dead."},{"name":"Maps, compass, GPS and a satellite communicator","source":"https://www.nps.gov/gaar/planyourvisit/basicinfo.htm","accessed":"2026-10-03","si":["hiking","expedition","river"],"booking_route":"affiliate referral to rei.com (AvantLink); Garmin inReach has no published programme","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":37,"blurb":"NPS: \"Topographic maps are essential in planning your course of travel\"; \"Carry your maps and a good compass (and a GPS unit is strongly encouraged if you have access to one)\" (backpacking page). Basic info: there is no cellular service; bring two forms of communication - \"Satellite phones are an excellent method of two-way communication in Alaska''s backcountry\", and messaging devices with emergency SOS are available for rental in Fairbanks."},{"name":"Insect protection, rain gear and layers","source":"https://www.nps.gov/gaar/planyourvisit/weather.htm","accessed":"2026-10-03","si":["hiking","river","senior","family"],"booking_route":"affiliate referral to rei.com (AvantLink) or Amazon Associates","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":38,"blurb":"NPS: \"Insect protection is a must during the summer months\"; thunderstorms are frequent June through July, so bring rain gear and layered clothing - snow can fall in nearly every month, so \"always be prepared for colder-than-expected conditions.\" Self-contained stoves are \"strongly recommended. Fires are often impractical\" (camping page)."}],"faq":[{"q":"How do I get to Gates of the Arctic National Park?","a":"Through Fairbanks, then by air or on foot. The NPS: \"Access to the park begins in Fairbanks, Alaska\" and \"Most visitors access the park by air taxi, in small aircraft equipped with floats or tundra tires.\" Gateways are Bettles (a visitor center, and \"Visitors can fly into the park from Bettles\"), Anaktuvuk Pass (\"Fly into this small Nunamuit village on one of the daily flights from Fairbanks and walk into the park from the airstrip\") and Coldfoot (\"Drive 280 miles north from Fairbanks up the Dalton Highway or fly in\").","source":"https://www.nps.gov/gaar/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you drive to Gates of the Arctic National Park?","a":"Not into it. \"Gates of the Arctic is a wilderness park, with no roads or trails into the park lands.\" The Dalton Highway \"parallels the eastern boundary of the park and it is possible to hike into the park from the road\"; it is \"a mostly unpaved, two lane industrial road, with no amenities or services between Fairbanks and Coldfoot.\"","source":"https://www.nps.gov/gaar/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"When is the best time to visit Gates of the Arctic National Park?","a":"It depends on the trip. The NPS: \"Mid-June to September is usually the best time for backpacking and hiking\"; July through August for float trips; \"November through March is the best time for viewing the Aurora Borealis.\" Float plane service ends on September 23, and in May''s break-up \"the ice on the rivers is getting soft and mushy and starting to break apart.\"","source":"https://www.nps.gov/gaar/planyourvisit/weather.htm","accessed":"2026-10-03"},{"q":"Does Gates of the Arctic National Park have a visitor center?","a":"Three, all outside the park. Bettles Ranger Station: \"7 days a week, 8:00 a.m. to 5:00 p.m., from July 1 to September 25\". The Arctic Interagency Visitor Center at mile 175 of the Dalton Highway in Coldfoot, open daily in summer. The Fairbanks Alaska Public Lands Information Center: \"7 days a week 8am-6 pm from May 25-September 11th\". Anaktuvuk Pass also has a ranger station, staffed April to the end of September (anaktuvuk.htm).","source":"https://www.nps.gov/gaar/planyourvisit/accessibility.htm","accessed":"2026-10-03"},{"q":"Can you camp in Gates of the Arctic National Park?","a":"Yes, anywhere suitable - there are no campgrounds. \"There are no designated campsites in Gates of the Arctic National Park and Preserve.\" \"Gravel bars make excellent campsites since they often have fewer mosquitoes than other sites\"; \"locate your camp well above current water levels.\" A certified bear-resistant food container \"is required in all Alaskan parks\", and the NPS recommends tent, cook area and container \"all 100 yards apart in a triangle formation.\"","source":"https://www.nps.gov/gaar/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"Can you hunt in Gates of the Arctic National Park?","a":"Only in the preserve. \"Sport hunting and trapping are permitted in Gates of the Arctic National Preserve, but not in Gates of the Arctic National Park.\" An Alaska State hunting licence is required for hunters 16 or older, under State regulations for Game Management Units 23, 24 and 26; guided hunts need an NPS Concession Contract or Commercial Use Authorization.","source":"https://www.nps.gov/gaar/planyourvisit/hunting.htm","accessed":"2026-10-03"},{"q":"What animals live in Gates of the Arctic National Park?","a":"The NPS names caribou (\"Caribou trek from their boreal forest wintering grounds to their calving areas on the coastal plain\"), grizzly and black bears, moose, Dall''s sheep, muskox, lynx, beavers, snowshoe hares, arctic ground squirrels, lemmings and voles, wood frogs, arctic terns, ptarmigan and common loons; \"Whitefish, northern pike and grayling feast in the rivers and lakes.\"","source":"https://www.nps.gov/gaar/learn/nature/wildlife.htm","accessed":"2026-10-03"},{"q":"How many acres is Gates of the Arctic National Park?","a":"8.4 million acres. The park was \"created to preserve and protect 8.4 million acres of the diverse arctic ecosystems of Alaska''s central Brooks Range\" and \"serves as the headwaters for six Wild Rivers.\"","source":"https://www.nps.gov/gaar/planyourvisit/basicinfo.htm","accessed":"2026-10-03"},{"q":"Do people live in Gates of the Arctic National Park?","a":"Yes. \"Situated inside the park''s boundaries, at the top of a wide 2,100 foot mountain pass, the village of Anaktuvuk Pass is a great place to start your exploration of Gates of the Arctic.\" Its inhabitants are primarily inland Inupiat people who hunt caribou for subsistence; the Simon Paneak Memorial Museum has \"Exhibits on Nunamiut history, life, and culture.\"","source":"https://www.nps.gov/gaar/planyourvisit/anaktuvuk.htm","accessed":"2026-10-03"},{"q":"Do you need tickets for Gates of the Arctic National Park and Preserve?","a":"No. \"No entrance fees or registration are required to enter the park\" and \"An entrance pass is not required to access Gates Of The Arctic National Park & Preserve.\" Groups should contact the park several months ahead about permits, and the park asks visitors to attend a free backcountry orientation at a visitor center.","source":"https://www.nps.gov/gaar/planyourvisit/fees.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Gates of the Arctic National Park: Brooks Range Wilderness & Wild Rivers | TravelWell","meta_description":"No roads, no trails, no entrance fee: 8.4 million acres of Brooks Range wilderness and six Wild Rivers, reached by air taxi from Bettles, Coldfoot or Fairbanks.","slug":"gates-of-the-arctic-national-park-alaska","primary_keyword":"Gates of the Arctic National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Gates of the Arctic National Park Arrigetch Peaks"}}'::jsonb, 109),
  ('kobuk-valley-alaska', '12A', 'Kobuk Valley National Park', 'United States', 'Arctic sand dunes and the caribou crossing', 'future', 'verified', 'mountainValley', 'Alaska', '{"adventure","wildlife","river","culture","expedition","parks"}', '{"remote","wild","adventurous","rugged"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Great Kobuk Sand Dunes","source":"https://www.nps.gov/kova/learn/nature/great-kobuk-sand-dunes.htm","accessed":"2026-10-03","si":["adventure","hiking","expedition","senior"],"booking_route":"none needed - no entrance fee; reached by air taxi or flightseeing charter","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"The largest active sand dunes in the Arctic\": the Great Kobuk Sand Dunes cover \"25 square miles of shifting, golden sand\" and \"Soaring dunes reach 100 feet into the air\" - \"a relic of the last Ice Age.\" \"Aircraft on wheels can land right on the sand,\" and \"Tents can be set up on any level surface.\" Near creeks, saturated sand \"causes the sand to behave more like a liquid than a solid\"."},{"name":"Western Arctic caribou migration","source":"https://www.nps.gov/kova/learn/nature/animals.htm","accessed":"2026-10-03","si":["wildlife","adventure","expedition"],"booking_route":"none needed - wild animals on public land","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Twice a year, 250,000 caribou pass through Kobuk Valley National Park on their annual migration\" - \"the 600 mile trek between their summer and winter grounds\". The park home page: \"thousands of migrating caribou\" cross the sculpted dunes."},{"name":"Paatitaaq - Onion Portage","source":"https://www.nps.gov/kova/learn/historyculture/paatitaaq-onion-portage.htm","accessed":"2026-10-03","si":["culture","wildlife","river"],"booking_route":"none needed - reached by river or air taxi","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"A stretch of river that has been the meeting ground for the Iñupiat, and their ancestors, for well over 8,000 years\"; \"A quarter of a million caribou migrate yearly across the Great Kobuk Sand Dunes\", and the site is still a seasonal gathering place for the caribou harvest. \"The story of Arctic archeology is dominated by one towering figure – J. Louis Giddings.\""},{"name":"Kobuk River float, Ambler to Kiana","source":"https://www.nps.gov/kova/planyourvisit/boating.htm","accessed":"2026-10-03","si":["river","adventure","group"],"booking_route":"none needed for independent travellers; organized recreational groups need a permit from the Chief Ranger","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"The 380-mile-long river flows west to Kotzebue Sound, with 61 miles traversing Kobuk Valley National Park.\" \"Starting in the village of Ambler, boating through the park and ending in the village of Kiana will take about 5-7 days.\" \"Collapsible canoes and kayaks work especially well\"; the dunes are \"accessible from the river via a 2-3 mile hike across the tundra\"."},{"name":"Little Kobuk and Hunt River Sand Dunes","source":"https://www.nps.gov/kova/learn/nature/great-kobuk-sand-dunes.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"none needed - free public land","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"Beside the main field lie \"the smaller Little Kobuk Sand Dunes and Hunt River Sand Dunes\"; together the dunes make \"30 square miles of towering sand.\" When the glaciers retreated 14,000 years ago they \"left behind 200,000 acres of rolling sand dunes.\""},{"name":"Flightseeing over the park","source":"https://www.nps.gov/kova/planyourvisit/flightseeing.htm","accessed":"2026-10-03","si":["senior","adventure","family","wildlife"],"booking_route":"through an authorized air charter in Kotzebue or Bettles","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":6,"blurb":"\"Hop aboard with Authorized charter companies out of Kotzebue or Bettles for a thrilling bird''s-eye view of the park''s landscape.\" Aircraft carry three to ten passengers by the hour or the day; day trips to the Great Kobuk Sand Dunes are popular. \"Prices can vary, but on average they run $1000 per hour or more.\""},{"name":"Northwest Arctic Heritage Center, Kotzebue","source":"https://www.nps.gov/kova/planyourvisit/nearby-attractions.htm","accessed":"2026-10-03","si":["family","senior","culture","group"],"booking_route":"none needed - free; PO Box 1029, Kotzebue, AK 99752; 907-318-2230","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"The headquarters and primary visitor center for Western Arctic National Parklands\": museum exhibits on Arctic ecology and Iñupiaq practices, films and ranger-led programs; (907) 318-2230. \"The Northwest Arctic Heritage Center in Kotzebue is wheelchair accessible\"; \"a wheelchair is available upon request\"."},{"name":"Kobuk Valley Junior Ranger programme","source":"https://www.nps.gov/kova/learn/kidsyouth/index.htm","accessed":"2026-10-03","si":["family","culture"],"booking_route":"none needed - free, by mail or in person","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"Anyone can become a Kobuk Valley National Park Junior Ranger by printing a copy of the Western Arctic National Parklands Junior Ranger book, completing the activities and mailing the book back to the Northwest Arctic Heritage Center.\" Kids \"can earn a Junior Ranger badge and a saber toothed tiger Junior Ranger patch\"; the Heritage Center runs weekly summer kids'' programs, (907) 318-2230."},{"name":"Sheefish, grayling and pike fishing","source":"https://www.nps.gov/kova/planyourvisit/fishing.htm","accessed":"2026-10-03","si":["adventure","river","wildlife"],"booking_route":"none needed in the park; an Alaska state fishing licence is required","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Sheefish, salmon, grayling, pike and Dolly Varden in the rivers are good to catch and good to eat.\" \"The Pah, Black and Pick rivers are good for sheefish.\" \"Anglers are required to have a fishing license and follow Alaska state fishing regulations.\" \"Local subsistence users may be fishing with set nets - give them a wide berth\"."},{"name":"Backcountry camping on the dunes and river","source":"https://www.nps.gov/kova/planyourvisit/backpacking.htm","accessed":"2026-10-03","si":["adventure","hiking","group"],"booking_route":"none needed - no permit for independent travellers; organized groups need a Chief Ranger permit","commission_status":"none","tier_absent_reason":"not-sold","wells":["stay"],"draw_rank":10,"blurb":"\"The most popular campsite is the Great Kobuk Sand Dunes\". \"There are also no designated campsites, and visitors must choose their own place to camp.\" The FAQ: \"There are no accommodations or public facilities within the park. Backcountry camping is the only way to spend the night.\""},{"name":"Midnight sun and northern lights","source":"https://www.nps.gov/kova/planyourvisit/weather.htm","accessed":"2026-10-03","si":["adventure","romance","senior"],"booking_route":"none needed - a natural phenomenon","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"The sun does not set between June 3rd and July 9th\"; in winter \"The sun is above the horizon only 1 ½ hours on December 21st\". Northern lights are active year-round and best seen in winter''s darkest nights."},{"name":"Winter travel by ski, snow machine and dog team","source":"https://www.nps.gov/kova/planyourvisit/things2do.htm","accessed":"2026-10-03","si":["adventure","expedition"],"booking_route":"none needed - self-supported","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"The NPS lists winter activities - \"snow machining, skiing and dog mushing\" - for those with \"Arctic winter survival skills\". In winter, chartered aircraft may land on skis, and visitors bring their own skis, snowshoes, dog teams or snowmobiles."},{"name":"Arctic tern and the summer birds","source":"https://www.nps.gov/kova/learn/nature/animals.htm","accessed":"2026-10-03","si":["wildlife","senior"],"booking_route":"none needed - wildlife on public land","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"The arctic tern flies \"all the way from the coast of Antarctica - the longest migration of any bird in the world.\" \"Ducks, cranes, loons, geese and swans\" \"make the valley their home for a few months each year.\" Grizzly bears, wolves and moose share the valley."},{"name":"Mount Angayukaqsraq","source":"https://www.nps.gov/kova/faqs.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - trailless public land","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"The park''s highest point: \"Mount Angayukaqsraq – is 4760 feet high.\" \"Kobuk\" is an Inupiaq word meaning \"big river\", for the Kobuk River valley running through the park''s center."},{"name":"Bear-resistant food container, loaned free","source":"https://www.nps.gov/kova/planyourvisit/bear-safety.htm","accessed":"2026-10-03","si":["hiking","adventure","wildlife"],"booking_route":"free loan at the Northwest Arctic Heritage Center; to own one, affiliate referral to BearVault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":15,"blurb":"NPS: \"Animal-resistant food containers are available to borrow from the Northwest Arctic Heritage Center\"; containers are loaned free, reserved by calling (907) 318-2230 no more than one month before the trip. \"Keep your camp area clean and never bring food, even in the proper containers, into your tent.\""},{"name":"Bear spray for the backcountry","source":"https://www.nps.gov/kova/planyourvisit/backpacking.htm","accessed":"2026-10-03","si":["hiking","wildlife","adventure"],"booking_route":"affiliate referral to Counter Assault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":16,"blurb":"NPS: bring \"appropriate clothing, water and bear spray when you''re hiking in the backcountry.\" The bear-safety page: \"Stay Alert\", \"Be Visible & Make Noise\", \"Avoid Bears\"."},{"name":"Rain gear, non-cotton layers and rubber boots","source":"https://www.nps.gov/kova/planyourvisit/weather.htm","accessed":"2026-10-03","si":["hiking","adventure","river","senior"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":17,"blurb":"NPS: layers of \"polypropylene, fleece, wool, or fur\", \"a breathable rain jacket and rain pants\", sturdy hiking boots and \"knee-high rubber/neoprene boots for wet terrain.\" \"Avoid wearing clothing made of cotton.\" \"Exposure and hypothermia are real threats to travelers.\""},{"name":"Bug jackets, head nets and repellent","source":"https://www.nps.gov/kova/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","family","river"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":18,"blurb":"NPS: \"Alaska is famous for mosquitoes, and for good reason, so carry bug protection when traveling in the park.\" Bug jackets, head nets and insect repellent are recommended, and black flies persist through fall."},{"name":"Map, compass and GPS","source":"https://www.nps.gov/kova/planyourvisit/backpacking.htm","accessed":"2026-10-03","si":["hiking","adventure","expedition"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":19,"blurb":"The park has \"no roads, trails, calculated mileages or specialized maps\", so the NPS recommends \"all visitors being prepared with map, compass, and GPS as well as the knowledge to use all three\"."},{"name":"Gates of the Arctic and Kobuk Valley (Arctic Wild)","source":"https://arcticwild.com/trip/base-camp/alaska-national-parks-gates-kobuk-2027/","accessed":"2026-10-03","si":["group","expedition","adventure","hiking"],"booking_route":"own website Reservation Request form; 907.479.8203","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":20,"blurb":"A 5-day guided base-camp trip from Kotzebue, \"July 17-21, 2027\", $9,100: two days on the Great Kobuk Sand Dunes - \"The largest dune complex in the North American Arctic\", with \"sand ridges over 200 feet tall\" - then two days in Gates of the Arctic. Includes round-trip airfare, wilderness meals, cooking equipment, base camp tent and professional guides. Booked by Reservation Request form and deposit."},{"name":"Alaska''s Northern National Parks: Krusenstern, Kobuk, Gates (Arctic Wild)","source":"https://arcticwild.com/trip/base-camp/alaska-parks-kobuk-gates-krusenstern-2027/","accessed":"2026-10-03","si":["group","expedition","culture","wildlife"],"booking_route":"own website Reservation Request form and deposit; 907.479.8203","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":21,"blurb":"A 7-day guided trip from Kotzebue, \"July 5-11, 2027\", $10,200: \"The Great Kobuk Dunes are like the Sahara but with wolves, moose, and cranes\" - 2.5 days on the dunes and at the Onion Portage archaeological sites, then Gates of the Arctic and Cape Krusenstern, where \"limestone hills meet the cold Arctic Ocean\". Includes round-trip airfare from Kotzebue, meals, camping equipment and guides."},{"name":"Brooks Range Aviation Gates and Kobuk flight tour, Bettles","source":"https://www.brooksrange.com/trips-tours/","accessed":"2026-10-03","si":["senior","adventure","group","family"],"booking_route":"phone 907-692-5444 (Bettles, June-September) / 907-474-0595 (Fairbanks)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":22,"blurb":"From Bettles, the Gates of the Arctic and Kobuk Valley package \"typically lasts 4 to 5 hours\", with \"a landing either directly on the Kobuk dunes—or on the river just north of it\" - \"the largest active dune field above the Arctic Circle in North America.\" Per person: $1,995 for two passengers down to $1,595 for six. Bettles 907-692-5444 (June-September), Fairbanks 907-474-0595 (year-round)."},{"name":"Golden Eagle Outfitters, Kotzebue","source":"https://alaska.org/detail/golden-eagle-outfitters-flightseeing-air-taxi","accessed":"2026-10-03","si":["adventure","senior","wildlife"],"booking_route":"phone 907-388-5968 (Kotzebue) / 907-388-2225 (Delta Junction)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":23,"blurb":"\"Experience the thrill of flightseeing in areas that most tours can''t reach\": custom flightseeing and air-taxi drop-off and pick-up from Kotzebue or Delta Junction, year round; flights to Kobuk Valley from Kotzebue, with popular 4-hour trips including a short landing. \"All trips are custom and are a per-hour rate based on the aircraft. Call or email for a quote.\" Kotzebue 907-388-5968."},{"name":"Bering Air, Kotzebue hub","source":"https://www.beringair.com/about/our-destinations/","accessed":"2026-10-03","si":["adventure","river","culture"],"booking_route":"own website flight schedule and contact page","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly","move"],"draw_rank":24,"blurb":"\"Bering Air provides all of your air transportation solutions for Alaska and beyond\" - scheduled service, statewide charter and helicopters from Nome, Kotzebue and Unalakleet, \"Since 1979\". From Kotzebue it serves the Kobuk River villages of Ambler, Kiana, Kobuk, Noorvik and Shungnak. Travel Alaska: \"Call Bering Air for a flightseeing trip up the Kobuk River and to the far-flung villages along the way.\""},{"name":"Wright Air Service, Fairbanks","source":"https://www.wrightairservice.com/","accessed":"2026-10-03","si":["adventure","senior"],"booking_route":"phone (907) 474-0502","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly","move"],"draw_rank":25,"blurb":"\"Proudly Serving Alaska Since 1966\", with daily scheduled service to \"more than 40 Interior and northern villages\" and charters \"to most locations in Alaska, including National Parks.\" Brooks Range Aviation points Bettles-bound travellers to Wright Air Service. Reservations (907) 474-0502."},{"name":"Northwest Alaska Backcountry Rentals, Kotzebue","source":"https://www.travelalaska.com/explore-alaska/locals-tips/a-locals-guide-to-kotzebue","accessed":"2026-10-03","si":["river","adventure"],"booking_route":"not stated on the page read","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities"],"draw_rank":26,"blurb":"Travel Alaska''s local guide to Kotzebue: \"Rent a kayak or raft from Northwest Alaska Backcountry Rentals.\" No rates, address or own website were found in this build."},{"name":"Bettles Lodge","source":"https://www.bettleslodge.com/","accessed":"2026-10-03","si":["adventure","group","senior","river"],"booking_route":"phone 1-907-692-5111 / 1-779-775-2990 or info@bettleslodge.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":27,"blurb":"\"Serving the Arctic Traveler since 1950\" in Bettles, \"35 miles north of the Arctic Circle\" - \"the ''jumping off'' point of adventure into the Brooks Mountain Range, Gates of the Arctic National Park & Preserve, Noatak National Preserve, and Kobuk Valley National Park.\" \"We offer unguided or guided wilderness trips including fishing, backpacking, canoe & rafting, photography and flight-seeing.\" 1-907-692-5111."},{"name":"Nullaġvik Hotel, Kotzebue","source":"https://www.nullagvikhotel.com/","accessed":"2026-10-03","si":["culture","group","senior","family"],"booking_route":"own website reservations portal","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"\"The Nullaġvik Hotel is more than a place to sleep. This is a gathering place to reflect, to rest, to meet and to dine in Kotzebue, the thriving hub of Northwest Alaska.\" \"Owned by NANA, the Iñupiat People of the Northwest Arctic. Managed by NMS.\" Alaska.org: \"71 guests rooms and 7 suites\", an observation room overlooking the Sound and a restaurant."},{"name":"Nullaġvik Hotel restaurant","source":"https://www.alaska.org/detail/nullagvik-hotel","accessed":"2026-10-03","si":["culinary","family","group"],"booking_route":"walk-in at the hotel","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"The hotel''s restaurant \"offers delicious food and fantastic views\" over Kotzebue Sound (alaska.org). Its own dining page refused the fetch (403), so hours and menu are not stated here."},{"name":"Bayside Inn and Restaurant, Kotzebue","source":"https://www.adn.com/food-drink/article/bayside-inn-and-restaurant/2009/11/09/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"phone 907-442-3600 (as given in the 2009 review)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","stay"],"draw_rank":30,"blurb":"Anchorage Daily News review dated 9 November 2009: at 330 Shore Ave. overlooking Kotzebue Sound, \"a small arm of the Chukchi Sea\", serving \"Chinese-American fare\", with an upper-level lounge for hotel guests; 907-442-3600. The review is 2009 - its hours are not carried here and current opening was not confirmed in this build."},{"name":"Kotzebue, the gateway on Kotzebue Sound","source":"https://www.travelalaska.com/explore-alaska/locals-tips/a-locals-guide-to-kotzebue","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"none needed - a town; scheduled flights from Anchorage","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":31,"blurb":"Travel Alaska: the park is \"75 miles east of Kotzebue\", reached by \"Air taxi from Kotzebue or Bettles\". The local guide: \"In early June, skip bedtime at the Nullaġvik Hotel and take a walk along Front Street\"; \"In July and August, nets will be set off the beach and we''ll be fishing for salmon.\""},{"name":"Sulianich Art Gallery, Kotzebue","source":"https://www.travelalaska.com/explore-alaska/locals-tips/a-locals-guide-to-kotzebue","accessed":"2026-10-03","si":["culture","senior","group"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop"],"draw_rank":32,"blurb":"\"Stop in at the Sulianich Art Gallery. Local and Alaska Native art festoons the walls and display cases.\" The NPS describes the Sulianjich Art Center as \"a nonprofit organization that markets the work of Northwest Alaskan artists.\""},{"name":"Kobuk 440 sled dog race","source":"https://www.travelalaska.com/explore-alaska/locals-tips/a-locals-guide-to-kotzebue","accessed":"2026-10-03","si":["spectator","culture","family"],"booking_route":"none needed - a public race start","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":33,"blurb":"\"Teams from around the state come north to compete in the Kobuk 440, a dog sled race that begins with a mass start here on the ice in front of the post office.\" No dated edition was read in this build."},{"name":"Alaska Geographic bookstore, Kotzebue","source":"https://www.travelalaska.com/explore-alaska/locals-tips/a-locals-guide-to-kotzebue","accessed":"2026-10-03","si":["family","culture"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop","gear"],"draw_rank":34,"blurb":"\"Walk a block north and check out the Northwest Arctic Heritage Center and Alaska Geographic bookstore.\" Maps and park books sit beside the park''s own visitor center."},{"name":"Cape Krusenstern National Monument","source":"https://www.travelalaska.com/explore-alaska/locals-tips/a-locals-guide-to-kotzebue","accessed":"2026-10-03","si":["wildlife","culture","adventure"],"booking_route":"none needed - public land; reached by air charter from Kotzebue","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":35,"blurb":"From Kotzebue: \"Muskoxen make their home along the coast and on the barren rounded mountains of Cape Krusenstern National Monument.\" Arctic Wild''s 7-day Northern National Parks trip pairs it with Kobuk Valley."},{"name":"Bettles, the Brooks Range gateway","source":"https://www.bettleslodge.com/","accessed":"2026-10-03","si":["adventure","senior"],"booking_route":"none needed - a village; scheduled flights from Fairbanks","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":36,"blurb":"A small village on the Koyukuk River in the Brooks Range foothills, \"35 miles north of the Arctic Circle\" - one of the two towns where, the NPS says, Kobuk Valley''s air taxi offices are located. Brooks Range Aviation recommends \"spending a night in Bettles\" before a park flight."}],"faq":[{"q":"How do you get to Kobuk Valley National Park?","a":"By plane. The NPS: \"There are no roads to provide access, so planes take care of most transportation needs.\" Commercial airlines serve Anchorage to Kotzebue and Fairbanks to Bettles, and from those towns visitors use \"authorized air taxis\" to reach the park.","source":"https://www.nps.gov/kova/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you drive to Kobuk Valley National Park?","a":"No. \"Kobuk Valley National Park is very remote. There are no roads to provide access, so planes take care of most transportation needs.\"","source":"https://www.nps.gov/kova/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit Kobuk Valley National Park?","a":"For floating the river the NPS says \"July, August and early September are preferable\"; June and July bring the peak of the mosquitoes.","source":"https://www.nps.gov/kova/faqs.htm","accessed":"2026-10-03"},{"q":"Where do you stay in Kobuk Valley National Park?","a":"In a tent. \"There are no accommodations or public facilities within the park. Backcountry camping is the only way to spend the night.\"","source":"https://www.nps.gov/kova/faqs.htm","accessed":"2026-10-03"},{"q":"How many acres is Kobuk Valley National Park?","a":"\"Of the approximately 1.7 million acres comprising Kobuk Valley National Park, approximately 190,000 acres were designated as wilderness.\"","source":"https://www.nps.gov/kova/learn/index.htm","accessed":"2026-10-03"},{"q":"When was Kobuk Valley National Park established?","a":"It was a \"National Monument - December 1, 1978\" and became a \"National Park - December 2, 1980\".","source":"https://www.nps.gov/kova/faqs.htm","accessed":"2026-10-03"},{"q":"Does Kobuk Valley National Park have a visitor center?","a":"Yes, in Kotzebue: the Northwest Arctic Heritage Center is \"the headquarters and primary visitor center for Western Arctic National Parklands\", with exhibits, films and ranger-led programs; (907) 318-2230.","source":"https://www.nps.gov/kova/planyourvisit/nearby-attractions.htm","accessed":"2026-10-03"},{"q":"How big are the Kobuk Valley National Park sand dunes?","a":"\"The largest active sand dunes in the Arctic\": the Great Kobuk Sand Dunes cover \"25 square miles of shifting, golden sand\", and with the Little Kobuk and Hunt River dunes the fields total \"30 square miles of towering sand.\" \"Aircraft on wheels can land right on the sand.\"","source":"https://www.nps.gov/kova/learn/nature/great-kobuk-sand-dunes.htm","accessed":"2026-10-03"},{"q":"When is the caribou migration in Kobuk Valley National Park?","a":"Spring and fall: \"Twice a year, 250,000 caribou pass through Kobuk Valley National Park on their annual migration\", on \"the 600 mile trek between their summer and winter grounds\".","source":"https://www.nps.gov/kova/learn/nature/animals.htm","accessed":"2026-10-03"},{"q":"How much does it cost to go to Kobuk Valley National Park?","a":"The park itself is free - it \"does not have an entrance gate, nor does it collect any fees to travel or camp in the park.\" The cost is the aircraft: the NPS says flightseeing charters \"on average they run $1000 per hour or more.\"","source":"https://www.nps.gov/kova/planyourvisit/flightseeing.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Kobuk Valley National Park: Arctic Sand Dunes & Caribou | TravelWell","meta_description":"No road, no fee, no campground: fly in from Kotzebue or Bettles to the Great Kobuk Sand Dunes, Onion Portage and 250,000 migrating caribou.","slug":"kobuk-valley-national-park-alaska","primary_keyword":"Kobuk Valley National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Great Kobuk Sand Dunes Kobuk Valley National Park caribou"}}'::jsonb, 110)
