insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('hawaii-volcanoes-hawaii', '12A', 'Hawai''i Volcanoes National Park', 'United States', 'The summit of Kīlauea, erupting in episodes inside Halemaʻumaʻu since December 2024, with a road down to the sea, a lit lava tube and a rainforest village at the gate', 'future', 'verified', 'mountainValley', 'Hawai''i', '{"hiking","adventure","glamping","culture","expedition","parks"}', '{"dramatic","wild","rugged","tropical"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Kīlauea eruption viewing, Crater Rim Drive","source":"https://www.nps.gov/havo/planyourvisit/eruption-viewing.htm","accessed":"2026-10-02","si":["adventure","senior","family","romance"],"booking_route":"none needed - park entrance pass only","commission_status":"none","tier_absent_reason":"not-sold","blurb":"an episodic lava-fountaining eruption inside Halemaʻumaʻu since December 23, 2024 (\"more than 50 eruptions\"), seen from Uēkahuna, Kīlauea Overlook, Kūpinaʻi Pali and Keanakākoʻi; the eruption area is closed; lots typically fill by 10 a.m.; USGS: \"relatively quiet\" on 2026-10-01"},{"name":"Welcome Center","source":"https://www.nps.gov/havo/planyourvisit/welcome-center.htm","accessed":"2026-10-02","si":["family","senior"],"booking_route":"walk-in","commission_status":"none","tier_absent_reason":"not-sold","blurb":"the temporary stand-in for Kīlauea Visitor Center during its renovation, 1.25 miles beyond the entrance station, 9 a.m. to 4:45 p.m. daily, with the daily schedule of ranger-led activities and a Hawaiʻi Pacific Parks Association store"},{"name":"Chain of Craters Road","source":"https://www.nps.gov/havo/planyourvisit/ccr_tour.htm","accessed":"2026-10-02","si":["adventure","senior","family","wildlife"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"18.8 miles (30.3 km) to the end of the road\" down Kīlauea to the sea, with Maunaulu and Puʻuloa stops; no food, water or fuel; vault toilets at Maunaulu and road''s end; NPS: \"Do not feed nēnē\""},{"name":"Nāhuku (Thurston Lava Tube)","source":"https://nps.gov/havo/planyourvisit/day-hike-nahuku.htm","accessed":"2026-10-02","si":["family","hiking","adventure"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a lava tube about 500 years old in rainforest, 1.5 miles round trip from Kīlauea Iki Overlook, lit 8 a.m. to 8 p.m.; parking \"extremely limited\"; NPS hazards: rockfall, low ceilings, standing water"},{"name":"Kīlauea Iki Trail","source":"https://www.nps.gov/havo/planyourvisit/hike_day_kilaueaiki.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 3.3-mile loop from the overlook, 2 to 3 hours, \"Steep and rocky, descent & ascent 400 feet\" through rainforest onto a crater floor; overlook parking \"extremely limited\""},{"name":"Puʻuloa Petroglyphs","source":"https://www.nps.gov/havo/planyourvisit/hike_day_puuloa.htm","accessed":"2026-10-02","si":["culture","hiking","family","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"1.4 miles round trip across a 500-550-year-old lava field from Chain of Craters Road to \"approximately 23,000 petroglyphs\", viewed from a boardwalk"},{"name":"Summit day hikes: Devastation Trail, Haʻakulamanu (Sulphur Banks), Halemaʻumaʻu Trail, Kīpukapuaulu","source":"https://www.nps.gov/havo/planyourvisit/hikes_day.htm","accessed":"2026-10-02","si":["hiking","senior","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"the NPS list runs from Devastation''s paved path to Haʻakulamanu, \"where volcanic gases have deposited colorful crystals\", the Halemaʻumaʻu Trail \"down to the floor of Kīlauea caldera\" and the Kīpukapuaulu botanical loop"},{"name":"Kahuku Unit, Kaʻū","source":"https://www.nps.gov/havo/planyourvisit/kahuku.htm","accessed":"2026-10-02","si":["hiking","culture","wildlife"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"the park''s ranching-history unit near mile-marker 70.5 on Highway 11, open Thursday to Sunday 8 a.m. to 4 p.m., eight trails from 0.4 to 7 miles round trip including the Glover Trail to a pit-crater rim; no potable water"},{"name":"Backcountry permits and the eight wilderness sites","source":"https://www.nps.gov/havo/planyourvisit/hike_bc.htm","accessed":"2026-10-02","si":["expedition","hiking","adventure"],"booking_route":"Recreation.gov; Backcountry Office in person 8 a.m.-4 p.m.","commission_status":"none","tier_absent_reason":"not-sold","blurb":"Kaʻaha, Halapē, Keauhou, ʻĀpua Point, Nāpau, Pepeiao Cabin, Red Hill Cabin and Mauna Loa Cabin; $10 a trip for up to 12 people and 7 nights; 75% of permits online up to 90 days ahead, 25% in person at the Backcountry Office"},{"name":"Volcano House","source":"https://www.nps.gov/havo/planyourvisit/lodging.htm","accessed":"2026-10-02","si":["romance","senior","culture"],"booking_route":"SynXis (reservation links on hawaiivolcanohouse.com); (844) 569-8849","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the park''s lodge on Crater Rim Drive, \"33 historic guest rooms, a dining room, snack bar, lounge, and gift shop, along with cultural events\", run by Hawai''i Volcanoes Lodge Company LLC"},{"name":"The Rim at Volcano House","source":"https://www.hawaiivolcanohouse.com/dining/","accessed":"2026-10-02","si":["culinary","romance","senior"],"booking_route":"Rezku (rezku.com); phone (808) 930-6910","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"breakfast buffet, lunch and dinner with the Kīlauea caldera and Halemaʻumaʻu as backdrop and live local music; a Certified Green Restaurant; dinner reservations required"},{"name":"Friends of Hawaiʻi Volcanoes National Park (Institute field seminars and private tours)","source":"https://fhvnp.org/excursions/","accessed":"2026-10-02","si":["culture","hiking","group","wildlife"],"booking_route":"online inquiry form; phone (808) 985-7373","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the park''s official philanthropic partner runs field seminars, private tours, monthly Sunday Walks in the Park, an October 17 artist residency conversation and Holidays in Kahuku on December 5, 2026"},{"name":"Nāmakanipaio Campground and camper cabins","source":"https://www.nps.gov/havo/planyourvisit/lodging.htm","accessed":"2026-10-02","si":["family","hiking","adventure"],"booking_route":"Volcano House (SynXis on hawaiivolcanohouse.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"tent and RV camping at 4,000 feet under eucalyptus and ʻōhiʻa, 26 sites per Hipcamp ($20 a night, $15 with a park pass); Volcano House manages \"10 newly refurbished camper cabins and campsites\" here"},{"name":"Kulanaokuaiki Campground","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["adventure","hiking","expedition"],"booking_route":"not observed (the NPS campground page loaded with its reservation section empty)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an 8-site tent and RV campground inside the park, \"~5 miles down Hulina [sic] Pali Road\" per Hipcamp, \"new campground with two wheelchair accessible sites\", toilets and picnic tables"},{"name":"The Tranquil Homestead, Mountain View","source":"https://www.hipcamp.com/en-US/land/hawaii-the-tranquil-homestead-6p0hv167","accessed":"2026-10-02","si":["glamping","family","romance"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an off-grid tiny-home cabin for up to four in a rainbow-eucalyptus rainforest, with ducks and peafowl to feed, full kitchen and composting toilet; 100% recommend"},{"name":"Sunrise Cabanas Panoramic Views, Nāʻālehu","source":"https://www.hipcamp.com/en-US/land/hawaii-sunrise-cabanas-panoramic-views-lz9hvwkp","accessed":"2026-10-02","si":["glamping","romance","culinary"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"two octagonal coastal cabanas and a campsite on a \"100% solar powered\" permaculture farm with \"over 100 varieties of tropical fruits\", looking to Mauna Loa, Kīlauea and the Kaʻū coast; Nāʻālehu is inside the Hurricane Lala advisory area"},{"name":"Paradise Yurts, Nāʻālehu","source":"https://www.hipcamp.com/en-US/land/hawaii-paradise-yurts-qeoh5o07","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a private yurt for two on 12 acres of citrus, avocado, breadfruit and banana, with outdoor rain shower and farm breakfast daily; Star Host, 100% recommend; Nāʻālehu is inside the Hurricane Lala advisory area"},{"name":"Rainbow''s End Farm & Homestead","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["glamping","adventure"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"off-grid, solar-powered glamping on hand-cleared land with \"fancy forts\"; 2 sites, 97% of 135 reviews recommend"},{"name":"Yip Camp and Eco-Retreat Center, Fern Forest","source":"https://www.hipcamp.com/en-US/land/hawaii-yip-camp-and-eco-retreat-center-88lhqrkm","accessed":"2026-10-02","si":["glamping","family","group","wellness"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an off-grid 3-acre rainforest retreat at about 2,700 feet on Kīlauea with canvas glamping tents, a 140 sq ft loft cabin, tent sites and two no-hookup RV sites; solar power, rainwater catchment, fire pit"},{"name":"Ember & Fern Retreat","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["glamping","romance","wellness"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"three \"traditional Hawaiian style homes\" on rainwater-harvested land, cabin glamping with showers and WiFi; 99% of 39 reviews recommend"},{"name":"Coco Hut Glamping at Honua La''a, Road to the Sea, Kaʻū","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["glamping","ocean","adventure"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"two glamping cabins on 19 acres with access to a remote green sand beach 4 miles away; pets allowed, campfires"},{"name":"Road to the Sea Glamping, Kaʻū","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["glamping","ocean"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"beautiful furnished cabins\" on 20 off-grid acres; pets allowed, showers; 96% of 28 reviews recommend"},{"name":"Moon Garden Getaway, Mountain View","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["glamping","family","group"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"tent, RV and glamping on a Star Host farm with volleyball, frisbee golf and tetherball; 99% of 350 reviews recommend"},{"name":"The Kikala Waterfall Lodge, Hilo area","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["glamping","wellness","romance"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"four cabin and glamping sites on \"14 acres of riverfront Cloud forest\" with a Zendo meditation space"},{"name":"The Bali Hale, Puna","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["glamping","wellness","romance"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a screened glamping bungalow on a secluded half-acre with a yoga platform; 99% of 58 reviews recommend"},{"name":"Farm to Table Hawaii, Hilo area","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["glamping","culinary","family"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"tents, a dome and a tiny home on a farm offering \"farm-to-table meals\" and \"cooking classes\" with Chef Justine Ma"},{"name":"Camp South Pt Green/Blacksand Beach, Waiʻōhinu","source":"https://www.hipcamp.com/en-US/land/hawaii-camp-south-pt-green-blacksand-beach-7rvhypp8","accessed":"2026-10-02","si":["group","ocean","adventure"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 22-acre property with RV/tent sites, group camping for 25 and two rooms, potable water and hot showers, \"easy access to Southpoint, Greensand and Blacksand Beaches\"; Waiʻōhinu is inside the Hurricane Lala advisory area"},{"name":"Hawaii Island''s Best Campsites (Hawaii Island Resort), Nāʻālehu","source":"https://www.hipcamp.com/en-US/land/hawaii-hawaii-island-s-best-campsites-dw9hdpl2","accessed":"2026-10-02","si":["family","culinary"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"five dispersed RV, van and tent sites in an 8-acre macadamia orchard with hot showers and a heated saltwater pool with water slide; Hipcamp 2023 \"Best in Hawaii: 3rd place\"; Nāʻālehu is inside the Hurricane Lala advisory area"},{"name":"Papa''s Hawaiian Orchid Farm, Pāhoa","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/hawai-i-volcanoes/all","accessed":"2026-10-02","si":["adventure","family"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a tent and RV site on a \"commercial orchid farm\" with a \"lava tube on the property\"; 98% of 390 reviews recommend"},{"name":"Hawaii Forest & Trail - Volcano Direct Hiking Adventure","source":"https://www.hawaii-forest.com/tours/volcano-direct-hiking-adventure/","accessed":"2026-10-02","si":["hiking","adventure","group","senior"],"booking_route":"FareHarbor","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 10-hour guided day into the park with naturalist guides, lunch and all gear, adults from $259, departing Kona weekly with Waikoloa and Hilo pickups; the operator cites \"a continuous commercial operating permit for over three decades\""},{"name":"KapohoKine Adventures, Hilo","source":"https://www.kapohokine.com/","accessed":"2026-10-02","si":["adventure","family","group"],"booking_route":"FareHarbor","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"volcano tours, ziplines and ATV from the Grand Naniloa lobby on Banyan Drive; the Evening Volcano Explorer from Waikoloa/Kohala runs about 11 hours with dinner ($229, listed down from $295.99)"},{"name":"Paradise Helicopters","source":"https://www.paradisecopters.com/","accessed":"2026-10-02","si":["adventure","romance","ultra"],"booking_route":"FareHarbor","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"helicopter tours from Hilo and Kona airports, with a \"Hawaii Lava Update\" on its site; tour names and prices for Kīlauea flights were not shown on the pages loaded"},{"name":"Blue Hawaiian Helicopters, Hilo and Waikoloa","source":"https://www.bluehawaiian.com/","accessed":"2026-10-02","si":["adventure","romance","ultra","senior"],"booking_route":"own site (bluehawaiian.com/en/tours); 1-800-745-2583","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"Discover Hilo (50 min, from $439) over \"newly formed volcanic landscapes\", Big Island Spectacular from Waikoloa (1 hr 45 min, from $719), and Waterfalls and Volcano by Air and Land (8 hours, from $1,009) with ground time at Kīlauea"},{"name":"Volcano Winery","source":"https://www.volcanowinery.com/","accessed":"2026-10-02","si":["wine","culinary","romance","senior"],"booking_route":"walk-in for tastings; tours need 24 hours'' advance booking, engine not observed; (808) 967-7772","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Volcano winery pouring grape wines, fruit blends and honey meads with estate teas and Kaʻū coffee; $20 six-pour tastings daily 12-5 p.m., Aliʻi Vineyard Tour $40, Wine Maker''s Tour $75, Kilauea Ki tea presentation $60"},{"name":"Kilauea Lodge and Restaurant, Volcano Village","source":"https://www.kilauealodge.com/","accessed":"2026-10-02","si":["culinary","romance","senior"],"booking_route":"own site (reservations.kilauealodge.com) for rooms; dining engine not observed; (808) 967-7366","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a small lodge of about 12 rooms at 19-3948 Old Volcano Road with an outdoor jacuzzi, tropical garden and an on-property restaurant serving \"fresh, locally sourced dishes\""},{"name":"Volcano Garden Arts and Café Ono, Volcano Village","source":"https://www.volcanogardenarts.com/","accessed":"2026-10-02","si":["culinary","culture","romance"],"booking_route":"walk-in; Volcano Artist Cottage via volcanoartistcottage.net","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a gallery of contemporary Hawaiian art, ceramics and sculpture in a redwood farmhouse on \"the 1908 Hopper Estate\" at 19-3834 Old Volcano Road; gallery daily 10-4 except Wednesday, Café Ono Thursday-Sunday 11-2"},{"name":"Hilo Farmers Market","source":"https://www.hilofarmersmarket.com/","accessed":"2026-10-02","si":["culinary","culture","family"],"booking_route":"walk-in","commission_status":"none","tier_absent_reason":"not-sold","blurb":"daily 7 a.m. to 3 p.m. at Kamehameha Avenue and Mamo Street in historic downtown Hilo, with \"tropical fruits, exotic flowers, handcrafted art, and authentic Hawaiian treats\""},{"name":"Mauna Loa Macadamia Nut Visitor Center, Keaʻau","source":"https://hawaiianhost.com/pages/maunaloa-visitor-center","accessed":"2026-10-02","si":["culinary","family","senior"],"booking_route":"walk-in","commission_status":"none","tier_absent_reason":"not-sold","blurb":"free macadamia samples and dairy-free ice cream, a self-guided nature walk of 25+ plant and animal species, and products from 25+ local makers at 16-701 Macadamia Road; Monday-Saturday 9-4, closed Sundays; open on the date of this build"},{"name":"Hilo Coffee Mill, Mountain View","source":"https://www.hilocoffeemill.com/","accessed":"2026-10-02","si":["culinary"],"booking_route":"walk-in; farm tours not shown on the page","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"mill and café at 17-997 Volcano Road on the Hilo-Volcano highway, \"Hawai''i''s favorite island coffee supplier since 2001\"; open 8:30-3 Tuesday-Sunday, 9-3 Monday"},{"name":"Kaʻū Coffee Mill, Pāhala","source":"https://www.kaucoffeemill.com/","accessed":"2026-10-02","si":["culinary"],"booking_route":"not observed (tours suspended); (808) 928-0550","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Kaʻū coffee and macadamia producer at 96-2694 Wood Valley Road; the site states \"Tours are not currently available due to road damage\""},{"name":"Punaluʻu Bake Shop, Nāʻālehu","source":"https://www.bakeshophawaii.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"closed - not bookable","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"The Southernmost Bakery in the U.S.A.\", known for Hawaiian sweet bread and malasadas; on the date of this build the shop, visitor centre and online store are \"temporarily closed due to damage from Hurricane Lala\""},{"name":"ʻImiloa Astronomy Center, Hilo","source":"https://imiloahawaii.org/","accessed":"2026-10-02","si":["culture","family","senior"],"booking_route":"own ticketing portal (sales.imiloahawaii.org)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"Polynesian navigation and Maunakea astronomy with Hawaiʻi Island''s only planetarium, at 600 ʻImiloa Place on the UH Hilo campus; Tuesday-Sunday 9-4:30"},{"name":"Hilo''s gardens and falls: Liliʻuokalani Gardens and Waiānuenue (Rainbow Falls)","source":"https://www.gohawaii.com/islands/hawaii-big-island/regions/hilo","accessed":"2026-10-02","si":["family","culture","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"per the state tourism site, a 30-acre Japanese garden with fishponds and pagodas, and the 80-foot Rainbow Falls in Wailuku River State Park; the Pacific Tsunami Museum is downtown"},{"name":"Lava Tree State Monument, Puna","source":"https://dlnr.hawaii.gov/dsp/parks/hawaii/lava-tree-state-monument/","accessed":"2026-10-02","si":["family","hiking","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 17.1-acre state monument with \"a forest of lava trees along an 0.7 mile loop trail\", daily during daylight, no fee; the state notes some Hawaiʻi island parks are still affected by hurricane recovery"},{"name":"Kalapana and Pāhoa, Puna","source":"https://www.gohawaii.com/islands/hawaii-big-island/regions/puna","accessed":"2026-10-02","si":["culture","culinary"],"booking_route":"walk-in","commission_status":"none","tier_absent_reason":"not-sold","blurb":"per the state tourism site, Kaimū and Kalapana were engulfed by Kīlauea lava in 1990; Uncle Robert''s ʻAwa Bar and Farmer''s Market stands by the flow, and Pāhoa is \"a former mill town with an inviting boardwalk\" with the weekend Makuʻu Farmers Market nearby"},{"name":"Volcano Village","source":"https://www.gohawaii.com/islands/hawaii-big-island/regions/puna","accessed":"2026-10-02","si":["culture","romance","culinary"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"per the state tourism site, a \"charming artist community located five minutes from Hawai''i Volcanoes National Park\"; the Cooper Center, \"the heartbeat of the Volcano Village Community\", sits here (its farmers market schedule did not load)"}],"faq":[{"q":"Is Kīlauea erupting right now?","a":"As of October 1, 2026, USGS states that an episodic lava fountaining eruption has been occurring in Halemaʻumaʻu crater since December 23, 2024, and that Kīlauea was relatively quiet that day. The NPS counts more than 50 eruptive episodes since December 2024. Activity comes in episodes with pauses between them, so lava on any given day is not certain.","source":"https://www.usgs.gov/volcanoes/kilauea","accessed":"2026-10-02"},{"q":"Where can I see the eruption from?","a":"The NPS names Uēkahuna, Kīlauea Overlook at Kūkamāhuākea (Steam Vents), Kūpinaʻi Pali and Keanakākoʻi along Crater Rim Drive. The eruption area itself is closed to the public, and parking lots typically fill by 10 a.m.","source":"https://www.nps.gov/havo/planyourvisit/eruption-viewing.htm","accessed":"2026-10-02"},{"q":"How much is the entrance fee?","a":"$30 per private vehicle, $25 per motorcycle and $15 per person on foot or bicycle (16 and over). The park does not accept cash.","source":"https://www.nps.gov/havo/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Is the Kīlauea Visitor Center open?","a":"No. The NPS says KVC, its restrooms, sidewalk, lānai and about half its parking are closed for renovation from February 18, 2025 to late 2026. The Welcome Center, 1.25 miles beyond the entrance station, stands in, open 9 a.m. to 4:45 p.m. daily.","source":"https://www.nps.gov/havo/planyourvisit/construction-closures.htm","accessed":"2026-10-02"},{"q":"Can I camp in the park?","a":"Yes. Volcano House manages camper cabins and campsites at Nāmakanipaio, Kulanaokuaiki is a second campground, and eight backcountry sites are available on a $10 permit booked through Recreation.gov up to 90 days ahead.","source":"https://www.nps.gov/havo/planyourvisit/hike_bc.htm","accessed":"2026-10-02"},{"q":"How far is the park from Hilo and Kona?","a":"The NPS gives 30 miles from Hilo (about 45 minutes) and 95 miles from Kailua-Kona on Highway 11 (2 to 2.5 hours).","source":"https://www.nps.gov/havo/planyourvisit/directions.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Hawai''i Volcanoes National Park: Kīlauea, Crater Rim & Where to Stay | TravelWell","meta_description":"Kīlauea''s episodic eruption as USGS states it, Crater Rim Drive, Chain of Craters, Nāhuku, campgrounds, and glamping from Volcano Village to Kaʻū and Puna.","slug":"hawaii-volcanoes-national-park-hawaii","primary_keyword":"Hawaii Volcanoes National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Hawai''i Volcanoes National Park, Hawai''i"}}'::jsonb, 111),
  ('haleakala-hawaii', '12A', 'Haleakalā National Park', 'United States', 'A 10,023-foot summit sacred to Native Hawaiians, a sunrise you reserve 60 days out for $1, a cinder crater you can sleep in, and a second district on the rainforest coast twelve miles past Hāna', 'future', 'verified', 'mountainValley', 'Hawai''i', '{"hiking","adventure","expedition","culinary","culture","parks"}', '{"dramatic","alpine","remote","tropical","pastoral"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Haleakalā sunrise (reservation required, 3-7 a.m.)","source":"https://www.nps.gov/hale/planyourvisit/sunrise.htm","accessed":"2026-10-02","si":["adventure","romance","senior","family"],"booking_route":"Recreation.gov only (calling the park or visiting in person cannot secure one); $1.00 per vehicle plus the entrance fee","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"In order to view sunrise at Haleakalā National Park, you will need to make a reservation ahead of time\" for the 3:00 AM - 7:00 AM window; released \"up to 60 days in advance\" at 7:00 am HST plus a portion \"2 days (48 hours) in advance\"; \"A visitor may only purchase one sunrise reservation per three-day period\"; NPS: \"Weather immediately before dawn and immediately after dusk are regularly wet, windy, and below freezing.\""},{"name":"The summit: Haleakalā Visitor Center and Pā Kaʻoao","source":"https://www.nps.gov/hale/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["culture","hiking","senior","family"],"booking_route":"none needed outside 3-7 a.m. - entrance pass only","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 0.4-mile, 100-ft walk \"up the puʻu next to Haleakalā Visitor Center to view ancient rock wall shelters and the crater\"; the park store there is open \"daily from sunrise - 12:00 pm\"; NPS: \"Please be quiet and respectful. The summit is sacred to Native Hawaiians.\""},{"name":"Keoneheʻeheʻe (Sliding Sands) Trail","source":"https://www.nps.gov/hale/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking","adventure","expedition"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"Hike downhill into the crater\": 0.5 mile round trip to the first overlook, the crater floor 3.9 miles down about 2,500 feet below, 11 miles as a full day across to the Halemauʻu Trail; the NPS rule is to allow twice the time to hike out"},{"name":"Halemauʻu Trail","source":"https://www.nps.gov/hale/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"Hike on a rocky path to a crater viewpoint\": 2.2 miles round trip, 1.1 miles to the viewpoint, 400 ft, past the \"Rainbow Bridge\" natural land bridge; also the route to Hōlua cabin and campsite (3.7 miles one way)"},{"name":"Supply Trail","source":"https://www.nps.gov/hale/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"4.6 miles round trip, 975 ft, \"Hike to the junction with the Halemauʻu Trail\""},{"name":"Leleiwi Overlook","source":"https://www.nps.gov/hale/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["senior","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"Short walk to a crater viewpoint\", 0.30 mile round trip, 100 ft - the shortest crater view on the NPS trail list"},{"name":"Hosmer Grove trail","source":"https://www.nps.gov/hale/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["wildlife","family","senior","hiking"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 0.54-mile loop, 50 ft: \"Compare non-native trees and native shrubland. View honeycreepers found nowhere else on earth.\""},{"name":"Hosmer Grove Campground","source":"https://www.nps.gov/hale/planyourvisit/hosmer-grove-campground.htm","accessed":"2026-10-02","si":["family","adventure","wildlife"],"booking_route":"Recreation.gov (online only)","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"Six designated sites\" in an open grassy area \"at nearly 7,000 feet (2134m)\" with picnic table, grill and potable water; $20 a night, three-night maximum; NPS: \"Come prepared for rain and cold weather!\""},{"name":"Wilderness cabins: Hōlua, Kapalaoa, Palikū","source":"https://www.nps.gov/hale/planyourvisit/wilderness-cabins.htm","accessed":"2026-10-02","si":["expedition","hiking","group","adventure"],"booking_route":"Recreation.gov or 1-877-444-6777, up to six months ahead","commission_status":"none","tier_absent_reason":"not-sold","blurb":"three historic crater cabins, \"12 padded bunks\" each, wood-burning and propane stoves, pit toilets and water nearby, \"no electricity\"; Hōlua 3.7 mi via Halemauʻu, Kapalaoa 5.6 mi and Palikū 9.3 mi via Keoneheʻeheʻe; $75 a night, three nights maximum; NPS: \"not checked by NPS staff daily\""},{"name":"Wilderness tent camping: Hōlua and Palikū","source":"https://www.nps.gov/hale/planyourvisit/wilderness-camping.htm","accessed":"2026-10-02","si":["expedition","hiking","adventure"],"booking_route":"Recreation.gov only, up to six months ahead","commission_status":"none","tier_absent_reason":"not-sold","blurb":"two hike-in primitive sites, $20 a night, five people and two tents a site (group sites ten and four), water \"must be filtered or treated before drinking\"; \"There is no cell phone service in Haleakalā Crater\""},{"name":"Stargazing at the summit","source":"https://www.nps.gov/hale/planyourvisit/stargazing.htm","accessed":"2026-10-02","si":["romance","family","adventure"],"booking_route":"none stated for evening visits","commission_status":"none","tier_absent_reason":"not-sold","blurb":"NPS advice: \"Turn off all white lights (including phones!)\"; use red lights \"only when necessary\"; \"the temperature can drop quickly when the sun goes down!\" - bring a hat, coat, long pants and warm shoes; overnight stays only in designated campgrounds"},{"name":"ʻĀhinahina (Haleakalā silversword)","source":"https://www.nps.gov/hale/learn/nature/silversword.htm","accessed":"2026-10-02","si":["wildlife","hiking","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"found on the \"aeolian desert cinder slopes of the crater\"; \"Silverswords live between 3 and 90 years or more\" and flower once, then die; once \"ripped up and taken home by visitors as souvenirs\", they \"now depend on management efforts for survival\" - stay on trails"},{"name":"Kīpahulu District and Visitor Center","source":"https://www.nps.gov/hale/planyourvisit/kipahulu.htm","accessed":"2026-10-02","si":["culture","hiking","ocean"],"booking_route":"none needed - entrance pass only","commission_status":"none","tier_absent_reason":"not-sold","blurb":"the park''s coastal district, reached \"12 miles beyond Hāna\", with \"views of waterfalls, sweeping ocean vistas, and Hawaiian cultural experiences\"; \"inhabited by native people for hundreds of years and remains an integral part of a thriving culture\"; Kīpahulu Visitor Center park store daily 9:00 - 5:00"},{"name":"Pīpīwai Trail","source":"https://www.nps.gov/hale/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking","adventure","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"4 miles round trip, 800 ft, \"Moderately strenuous\", \"through a freshwater stream and diverse forest areas with views of waterfalls\"; NPS: \"Flash floods and sudden rock falls can occur at any time! Entry and wading in the streams is not recommended.\""},{"name":"Kūloa Point Trail and the Pools of ʻOheʻo","source":"https://www.nps.gov/hale/planyourvisit/conditions.htm","accessed":"2026-10-02","si":["culture","senior","family","ocean"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"0.5 mile, 80 ft, \"past a Hawaiian cultural demonstration area to Kuloa Point\" with \"beautiful ocean views and archaeological sites\"; NPS status: \"The Pools of ʻOheʻo in the Kīpahulu District are not accessible for swimming. The pools can be viewed safely from the Kūloa Point Trail.\""},{"name":"Kīpahulu Campground","source":"https://www.nps.gov/hale/planyourvisit/kipahulu-campground.htm","accessed":"2026-10-02","si":["adventure","family","ocean"],"booking_route":"Recreation.gov, 30-day rolling window","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"20 sites total including 5 walk-in sites, 15 drive-in sites, and 1 group drive-in site\" above the ocean; $20 a night, three-night maximum; \"No water is available at the Kīpahulu Campground. There are no showers or electrical outlets\" (water station at the visitor center); \"Be prepared for rain, harsh sun, and mosquitoes\""},{"name":"Kīpahulu ʻOhana and Kapahu Living Farm","source":"https://www.kipahulu.org/","accessed":"2026-10-02","si":["culture","hiking","group"],"booking_route":"contact form, (808) 248-8673; no schedule or price published","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"a grassroots Hawaiian 501(c)(3) nonprofit organization founded in 1995\" that manages Kapahu Living Farm, a traditional wetland taro farm in the Kīpahulu District, under a partnership agreement with the park; lists Cultural Interpretive Hike Tours and ʻĀina education work days"},{"name":"Haleakalā EcoTours","source":"http://haleakalaecotours.com/","accessed":"2026-10-02","si":["adventure","senior","group","romance"],"booking_route":"Ponorez (ez-forms.ponorez.com); (808) 755-3345","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"listed on its own site as a \"Haleakala Park Authorized Concessioner\"; Haleakalā Sunrise Tour \"$230+ taxes & fees\", Sunset Tour $250+, plus summit, rainforest and Road to Hāna tours with NAI-certified guides; departs 810 Haiku Rd, Haiku"},{"name":"Bike Maui (Haleakala Bike Company)","source":"https://www.bikemaui.com/","accessed":"2026-10-02","si":["adventure","sports","group"],"booking_route":"Ponorez (ez-forms.ponorez.com/suppliers/bike-maui); (808) 575-9575","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"self-guided and guided downhill bike tours: Haleakala Sunrise self-guided $190, Morning $150, Express $79, guided sunrise $225, with discounts for bookings 72+ hours ahead; in-park portions run through sister company Haleakalā EcoTours; base at 810 Haiku Rd, Haiku"},{"name":"Maui Sunriders Bike Co., Pāʻia","source":"https://www.mauisunriders.com/","accessed":"2026-10-02","si":["adventure","sports","family"],"booking_route":"own site; 808-579-8970 (engine not observed)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"The original & most trusted self-guided bike tour experience for over 25 years. Ride at your own pace with full van support\" - Haleakalā self-guided, guided and Bike & Brew tours, plus a North Shore e-bike tour; operating since 2001, 71 Baldwin Ave, Pāʻia"},{"name":"Pony Express Tours - Crater Junction Ride","source":"https://www.ponyexpresstours.com/","accessed":"2026-10-02","si":["adventure","expedition","culture"],"booking_route":"reservation required (engine not observed)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"horseback down the Sliding Sands Trail into the crater: about 4 hours, 7.5 miles round trip, \"Descends 2,500 ft to crater floor\" with a picnic lunch, $182 + tax, 8:30 a.m., prior riding experience recommended; shorter Haleakala Ranch Paniolo (2 hr, $110) and Mauka (1.5 hr, $95) rides at 4,000 feet"},{"name":"Surfing Goat Dairy, Kula","source":"https://surfinggoatdairy.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"own site online reservations; (808) 878-2870","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an \"award-winning goat dairy farm\" on Haleakalā''s slopes at 3651 Omaopio Rd with a Daily Casual Tour, Baby Goat Interaction, the Golden Girl Experience (18+) and Evening Chores & Milking tours; Tuesday-Saturday 9:30-5"},{"name":"MauiWine, ʻUlupalakua","source":"https://www.mauiwine.com/","accessed":"2026-10-02","si":["wine","culinary","romance","senior"],"booking_route":"walk-in or own reservation system; +1 (808) 878-6058","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the Ulupalakua Vineyards tasting room at 14815 Piilani Hwy pouring estate wines, pineapple wines and the Rose Ranch collection, Tuesday-Sunday 11-5; the winery warns \"GPS MAY ROUTE INCORRECTLY\" and gives Highway 37 through Keokea"},{"name":"Ulupalakua Ranch Store & Grill","source":"https://www.ulupalakuaranch.com/","accessed":"2026-10-02","si":["culinary","culture","family"],"booking_route":"walk-in","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a working cattle ranch established in 1845, \"one of Hawaii''s largest working cattle ranches\"; the grill serves \"grass fed beef, venison, and elk burgers sourced right from the pastures\", Tuesday-Sunday 11-4"},{"name":"Aliʻi Kula Lavender","source":"https://aliikulalavender.com/","accessed":"2026-10-02","si":["romance","culinary","senior","wellness"],"booking_route":"aklreservations@aklmaui.com or 808.878.3004","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a lavender farm at 1100 Waipoli Road, Kula, open Friday-Monday 10-4 (last entry 3:45), closed Tuesday-Thursday, with a gift shop and its \"sustainable aloha\" message"},{"name":"Kula Botanical Garden","source":"https://kbgmaui.com/","accessed":"2026-10-02","si":["family","senior","wildlife"],"booking_route":"walk-in; (808) 878-1715","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a garden established in 1971 at 638 Kekaulike, Kula, \"Open every day - 365 days a year\", self-guided tours 9 to 3:15; adults $15, children 6-12 $5; Maui-grown Christmas trees in December"},{"name":"Oʻo Farm, Kula","source":"https://www.oofarm.com/","accessed":"2026-10-02","si":["culinary","romance","wellness"],"booking_route":"Bookeo; 808.856.0141","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"a scenic parcel of land in upcountry Maui above Kula, dedicated to culinary farming and agritourism\" at 651 Waipoli Rd: a Coffee & Brunch Experience and a Farm-to-Table Lunch and Farmer Field Tour; \"A tour reservation is mandatory to access the property\""},{"name":"Grandma''s Coffee House, Keokea","source":"https://www.grandmascoffeehousemaui.com/","accessed":"2026-10-02","si":["culinary","family","senior"],"booking_route":"walk-in; online ordering","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a family coffee house at 9232 Kula Hwy whose story starts in 1918 when Grandma began roasting coffee; daily 7-2 with pumpkin bread, pineapple-coconut-macadamia muffins and \"the best organic coffee around\"; MauiWine routes visitors past it"},{"name":"Kula Bistro","source":"https://www.kulabistro.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in only","commission_status":"none","tier_absent_reason":"not-sold","blurb":"breakfast (7:30-10:30, not Monday or Tuesday), lunch and dinner (11-8) at 4566 Lower Kula Road; \"No Reservations, walk-ins only!\""},{"name":"Kula Lodge","source":"https://kulalodge.com/","accessed":"2026-10-02","si":["romance","culinary"],"booking_route":"own site; (808) 878-1535 (engine not observed)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"vacation chalets with lanais and electric fireplaces at 15200 Haleakala Hwy (Route 377); on the date of this build \"The main restaurant is closed indefinitely due to fire damage\" while a food truck and the Kula Marketplace run 7 a.m.-7 p.m."},{"name":"Kula Sandalwoods Inn","source":"https://www.kulasandalwoods.com/","accessed":"2026-10-02","si":["romance","culinary","senior"],"booking_route":"808.878.3523 or info@kulasandalwoods.com (engine not observed)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"six hillside cottages at 3,300 feet at 15427 Haleakalā Hwy with \"sweeping bi-coastal views of the islands of Moloka''i and Lana''i\" and a breakfast-and-lunch café; \"Native Hawaiian owned and operated\""},{"name":"Upcountry Farmers Market, Kulamalu","source":"https://www.upcountryfarmersmarket.com/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in","commission_status":"none","tier_absent_reason":"not-sold","blurb":"Saturdays 7-11 a.m. at 55 Kiopaa St (Kulamalu Town Center), \"over 100 local vendors showcasing the best of Maui\" - produce, flowers, fresh fish, baked goods and crafts"},{"name":"Hui Noʻeau Visual Arts Center, Makawao","source":"https://www.huinoeau.com/","accessed":"2026-10-02","si":["culture","senior","group"],"booking_route":"walk-in for gallery; classes via own site","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a nonprofit arts centre founded in 1934 on the historic Kaluanui Estate at 2841 Baldwin Avenue, Tuesday-Saturday 9-4, with exhibitions, a Gallery Shop and classes from ceramics and glassblowing to Hawaiian arts"},{"name":"Kula","source":"https://www.gohawaii.com/islands/maui/regions/upcountry-maui","accessed":"2026-10-02","si":["culinary","romance","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"per the state tourism site, \"In the heart of Upcountry Maui, Kula is a quaint, rustic area on the slopes of Haleakalā\" - the farm and lodging belt on the summit road"},{"name":"Makawao","source":"https://www.gohawaii.com/islands/maui/regions/upcountry-maui","accessed":"2026-10-02","si":["culture","culinary"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"per the state tourism site, \"Located on the mid-slopes of Maui''s Haleakalā volcano, Makawao has one foot in its plantation past and another in its thriving arts community\""},{"name":"Pāʻia","source":"https://www.gohawaii.com/islands/maui/regions/east-maui","accessed":"2026-10-02","si":["culture","ocean","culinary"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"per the state tourism site, \"the historic town of Pāʻia on Maui''s north coast\"; the NPS names Pāʻia as the place to refuel for Kīpahulu, since there is no gas in the park"},{"name":"Mama''s Fish House, Kūʻau","source":"https://www.mamasfishhouse.com/","accessed":"2026-10-02","si":["culinary","romance","ocean"],"booking_route":"phone (808) 579-8488, 9 a.m.-9 p.m. HST","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"open since 1973 at 799 Poho Place overlooking Kūʻau Bay, fish from local fishing families, a 2018 James Beard Foundation semi-finalist; \"books up months in advance\", bookings up to 18 months out; The Inn at Mama''s has beachfront lodging"},{"name":"Hāna","source":"https://www.gohawaii.com/islands/maui/regions/east-maui","accessed":"2026-10-02","si":["culture","romance","ocean"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"per the state tourism site, \"A charming small town where time seems an abstract concept and aloha is a way of life\"; the Pools of ʻOheʻo are \"15 minutes south of Hāna on Highway 31\""},{"name":"Hana-Maui Resort, Destination by Hyatt","source":"https://www.hanamauiresort.com/","accessed":"2026-10-02","si":["romance","wellness","culinary"],"booking_route":"Hyatt (hyatt.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"oceanfront bungalows, garden suites and villas at 5031 Hana Hwy where rooms \"intentionally lack televisions and clocks\"; Hana Ranch restaurant (farm-to-table, ocean-to-fork), Paniolo Bar, and a spa with lomi lomi"},{"name":"Hāna Farms","source":"https://www.hanafarms.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a farm stand, bakery (\"banana bread and desserts daily\") and The Bamboo Hale serving \"wood-fired pizza\" at 2910 Hana Highway, \"after mile marker 31, just after the ''Welcome to Hāna'' sign\"; Friday hours run to 8 p.m."},{"name":"Kahanu Garden and Piʻilanihale Heiau, Hāna","source":"https://ntbg.org/gardens/kahanu/","accessed":"2026-10-02","si":["culture","hiking","senior"],"booking_route":"own online reservation system","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a National Tropical Botanical Garden site at 650 Ulaino Rd, home to Piʻilanihale Heiau and described as \"a profound Hawaiian place\"; self-guided and guided tours, \"guided tours may sell out in advance\""},{"name":"Waiʻānapanapa State Park","source":"https://dlnr.hawaii.gov/dsp/parks/maui/waianapanapa-state-park/","accessed":"2026-10-02","si":["ocean","culture","hiking","family"],"booking_route":"gostateparks.hawaii.gov/waianapanapa","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"All visitors and commercial operators will need to make reservations to enter\"; open 7-6; non-residents $5 a person and $10 a vehicle; an \"ancient Hawaiian coastal trail which leads to Hana\" and a heiau; tent camping $30 and cabins $100 a night"},{"name":"Wahi Nanea Place of Relaxation, Kula","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/haleakala/all","accessed":"2026-10-02","si":["glamping","family","group"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"six tent, RV and cabin sites at 2,800 feet with picnic tables, grill, fire pit and a shared gazebo; 97% of 912 reviews recommend"},{"name":"Lokalani Gardens","source":"https://www.hipcamp.com/en-US/national-park/united-states/hawaii/haleakala/all","accessed":"2026-10-02","si":["glamping","wellness"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a \"Remote, off-grid farm...surrounded by wild, untamed land\" with two sites, medicinal plants and yoga sessions; one review on Hipcamp"},{"name":"Polipoli Spring State Recreation Area (closed)","source":"https://dlnr.hawaii.gov/dsp/parks/maui/polipoli-spring-state-recreation-area/","accessed":"2026-10-02","si":["expedition","hiking"],"booking_route":"closed - not bookable on the date of this build","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"Camping and lodging (one cabin) within the fog belt of the Kula Forest Reserve at 6200 foot elevation\", four-wheel drive required; state notice 10/1/26: \"Polipoli - remains CLOSED due to downed trees\""},{"name":"Hāna Lava Tube (Kaʻeleku Cave) (closed)","source":"https://www.mauicave.com/","accessed":"2026-10-02","si":["adventure","family"],"booking_route":"closed - not bookable","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the site states \"The cave has been temporarily closed by the government until further notice while they schedule an archaeological inventory survey of the cave\""}],"faq":[{"q":"Do I need a reservation for Haleakalā sunrise?","a":"Yes. Entry between 3 and 7 a.m. requires a sunrise reservation made on Recreation.gov. They are released up to 60 days in advance at 7 a.m. HST, with a further portion released 48 hours ahead, and one visitor may buy only one per three-day period.","source":"https://www.nps.gov/hale/planyourvisit/sunrise.htm","accessed":"2026-10-02"},{"q":"How much does it cost to visit Haleakalā?","a":"$30 per private vehicle, $25 per motorcycle or $15 per person, plus $1.00 for a sunrise reservation if you are entering between 3 and 7 a.m. The park does not accept cash.","source":"https://www.nps.gov/hale/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"How cold is it at the summit?","a":"The NPS says summit temperatures are at least 20 degrees colder than at sea level and often drop below freezing, and that weather just before dawn and after dusk is regularly wet, windy and below freezing.","source":"https://www.nps.gov/hale/planyourvisit/summit-district.htm","accessed":"2026-10-02"},{"q":"Can I swim at the Pools of ʻOheʻo?","a":"No. The NPS states the pools are not accessible for swimming and can be viewed from the Kūloa Point Trail. It warns that flash floods and sudden rock falls can occur at any time at Kīpahulu.","source":"https://www.nps.gov/hale/planyourvisit/conditions.htm","accessed":"2026-10-02"},{"q":"Can I stay overnight inside the crater?","a":"Yes, in three wilderness cabins (Hōlua, Kapalaoa, Palikū) at $75 a night or two tent sites at $20 a night, all reserved on Recreation.gov up to six months ahead. There is no cell phone service in the crater.","source":"https://www.nps.gov/hale/planyourvisit/wilderness-cabins.htm","accessed":"2026-10-02"},{"q":"How long is the drive?","a":"The NPS gives about 2.5 hours from Kahului to the summit, 3 hours from Wailea, 3.5 from Lahaina, and about 4 hours from Kahului to Kīpahulu. There is no gas in the park; refuel in Pukalani or Pāʻia.","source":"https://www.nps.gov/hale/planyourvisit/directions.htm","accessed":"2026-10-02"},{"q":"Can I ride a bike down Haleakalā?","a":"Commercial downhill bike rides inside the park have been under an NPS moratorium since 2008, with bike companies authorized to run van tours within the park. Operators such as Bike Maui and Maui Sunriders sell downhill tours; check with them where the ride begins.","source":"https://www.nps.gov/hale/learn/news/downhill-bicycle-tour-moratorium-continues-at-haleakala-national-park.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Haleakalā National Park: Sunrise Reservations, Crater Trails & Kīpahulu | TravelWell","meta_description":"The $1 sunrise reservation, Sliding Sands and the crater cabins, Pīpīwai at Kīpahulu, and the Upcountry farms, wine and stays from Kula to Hāna.","slug":"haleakala-national-park-hawaii","primary_keyword":"Haleakala National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Haleakala National Park, Maui"}}'::jsonb, 112)
